/* Conținutul cursului. Generat de tools/package.py din content_m1..m3.py. */
window.COURSE={"title":"Citim cetatea ca pe *un argument*","subtitle":"Trei lecturi de filosofie politică: natura umană, regimurile, ideologiile","project":"Urban Instances V3 · Cetatea citită","author":"Gelu-Emanuel Cebzan","contentAuthor":"Mihail Curelici","org":"LEETUCATION SRL","funding":"Finanțat de Municipiul Timișoara prin Centrul de Proiecte și Administrația pentru Sănătate și Educație.","about":{"id":"0.1","type":"about","k":"Despre acest e-learning","t":"Citim cetatea ca pe *un argument*","n":["Bun venit. Acest e-learning face parte din proiectul Urban Instances, a treia ediție: Cetatea citită. Conținutul îi aparține lui Mihail Curelici.","Proiectul citește orașul ca pe un text: îl privim atent, subliniem un detaliu, notăm pe margine.","Aici citim cetatea în sensul ei cel mai vechi: comunitatea politică. Trei module, trei întrebări.","Primul: ce raport există între natura umană și viața în comunitate. Al doilea: cum trebuie organizată puterea comună. Al treilea: cine stabilește binele comun.","Fiecare ecran are voce, iar elementele apar pe măsură ce le auzi. Poți pune pauză, poți relua, poți porni subtitrarea și poți schimba viteza.","În fiecare modul ai exerciții interactive, o verificare cu explicații și o fișă de lucru pe care o descarci la final. Bibliografia completă este în Resurse, unde îți poți nota și propriile lecturi.","Poți parcurge modulele în orice ordine, dar ele formează un ciclu: fiecare se încheie cu întrebarea de la care pornește următorul. Fiecare modul durează aproximativ douăzeci și cinci de minute."],"steps":[{"c":1,"h":"privim atent"},{"c":1,"h":"subliniem un detaliu"},{"c":1,"h":"notăm pe margine"}],"mods":[{"c":3,"m":0},{"c":3,"m":1},{"c":3,"m":2}],"how":[{"c":4,"i":"voice","t":"Voce, cu elementele sincronizate"},{"c":4,"i":"cc","t":"Subtitrare și viteză reglabilă"},{"c":5,"i":"ex","t":"Exerciții, verificări și fișe de lucru"},{"c":5,"i":"bib","t":"Resurse: bibliografie și notițele tale"}]},"final":{"id":"9.0","type":"final","k":"Final","t":"Ai citit *cetatea*","n":["Ai parcurs cele trei lecturi ale cetății: natura umană, regimurile, ideologiile.","Fiecare răspuns pe care l-ai întâlnit pornește de la o concepție despre om. Întrebarea care rămâne deschisă este și a ta.","Conținutul îi aparține lui Mihail Curelici. E-learningul a fost realizat de Gelu-Emanuel Cebzan, prin Leetucation, în proiectul Urban Instances, Cetatea citită.","Proiectul este finanțat de Municipiul Timișoara prin Centrul de Proiecte și Administrația pentru Sănătate și Educație."]},"modules":[{"id":"m1","num":"01","title":"Omul și *cetatea*","sub":"Natura umană și comunitatea","q":"Comunitatea împlinește natura omului, o constrânge sau o transformă?","thesis":"Concepția despre natura umană determină ce fel de putere politică socotim necesară.","cover":"m1_cover","screens":[{"id":"1.0","type":"cover","img":"m1_cover","mark":{"x":52,"y":30,"w":16,"h":34,"l":"citim cetatea"},"n":["Modulul unu. Omul și cetatea.","Oamenii trăiesc întotdeauna în grupuri. Asta nu se discută. Întrebarea este alta: ce raport există între natura umană și viața în comunitate?","Comunitatea împlinește natura omului, o constrânge sau o transformă?","Răspunsul nu este doar teoretic. Concepția pe care o ai despre om decide ce fel de putere comună socotești necesară.","În acest modul compari trei răspunsuri clasice, ale lui Aristotel, Hobbes și Rousseau, apoi trei viziuni contemporane. La final, verifici ce ai înțeles."],"goals":[{"c":4,"t":"Distingi natura umană de condiția umană, physis de nomos, comunitatea de societatea politică."},{"c":4,"t":"Explici de ce cetatea greacă a făcut posibilă dezbaterea despre legi."},{"c":4,"t":"Compari tezele lui Aristotel, Hobbes și Rousseau, cu argumentele pro și contra."},{"c":4,"t":"Deosebești viziunea liberală, comunitaristă și republicană asupra datoriei civice."}]},{"id":"1.1","type":"concept","k":"01 · Delimitarea problemei","t":"Nu dacă trăim împreună, ci *de ce*","img":"m1_physis","mark":{"x":8,"y":14,"w":42,"h":50,"l":"citim physis"},"n":["Faptul conviețuirii nu este disputat. Disputa filosofică privește temeiul asocierii: ce o explică și ce o justifică.","Ca să discuți corect, ai nevoie de trei distincții, chiar de la început.","Prima: natura umană și condiția umană. Natura umană înseamnă dispozițiile comune speciei: capacități, nevoi, tendințe. Condiția umană este situația în care se exercită ele: finitudinea, dependența, pluralitatea.","A doua: physis și nomos. Ceea ce este de la sine, prin natură, se opune la ceea ce este instituit prin convenție, lege sau obicei. Toată dezbaterea poate fi citită ca o dispută despre locul comunității politice pe această axă.","A treia: comunitate și societate politică. Comunitatea este un grup legat prin valori, practici și scopuri comune. Societatea politică este asocierea supusă unei puteri comune și unor legi."],"lead":{"c":0,"t":"Disputa privește *temeiul* asocierii: ce o explică și ce o justifică."},"notes":[{"c":2,"n":"01","h":"Natură umană / condiție umană","p":"dispoziții comune speciei · situația în care se exercită: finitudine, dependență, pluralitate"},{"c":3,"n":"02","h":"physis / nomos","p":"ce este de la sine, prin natură · ce este instituit prin convenție, lege, obicei"},{"c":4,"n":"03","h":"Comunitate / societate politică","p":"valori, practici, scopuri comune · o putere comună și legi"}]},{"id":"1.2","type":"concept","k":"02 · Cetatea greacă","t":"Comunitatea care își dă *singură* legile","img":"m1_polis2","mark":{"x":40,"y":48,"w":22,"h":13,"l":"citim polis"},"n":["Așezări urbane și cetăți-stat existau cu mult înainte, în Mesopotamia, în Egipt și în lumea feniciană.","Specificul grecesc este altul: comunitatea care își dă singură legile și le supune dezbaterii publice.","Inventarul cetăților arhaice și clasice numără aproximativ o mie de poleis.","Istoricul Jean-Pierre Vernant susține că raționalitatea filosofică și cetatea au aceleași condiții de posibilitate. În formula lui: rațiunea greacă este fiica cetății."],"notes":[{"c":0,"n":"01","h":"Înainte","p":"Mesopotamia, Egipt, lumea feniciană: așezări urbane și cetăți-stat"},{"c":1,"n":"02","h":"Specificul grecesc","p":"legi date de comunitate și supuse dezbaterii publice"}],"stat":{"c":2,"v":"≈ 1000","l":"de poleis în inventarul cetăților arhaice și clasice","r":"Hansen și Nielsen, 2004"},"quote":{"c":3,"t":"„Rațiunea greacă este fiica cetății.”","r":"Jean-Pierre Vernant, 1962"}},{"id":"1.3","type":"cards","k":"03 · Condițiile de posibilitate","t":"Șase condiții ale *cetății*","cols":3,"n":["Istoriografia invocă șase condiții.","Unu: fragmentarea geografică. Relieful și insularitatea au favorizat comunități mici și autonome, fără o autoritate imperială care să impună o lege unică.","Doi: o religie fără dogmă. Nu exista o carte sacră și nici o castă de preoți deținătoare a adevărului. Preoțiile erau magistraturi civice.","Trei: armata cetățenilor. Falanga hoplitică era formată din cetățeni care își procurau singuri echipamentul. Ipoteza că egalitatea militară a susținut egalitatea politică, numită revoluția hoplitică, rămâne disputată.","Patru: legea scrisă și publică. Din secolul al șaptelea înainte de Hristos, legile sunt inscripționate și expuse. Legea de la Dreros, din Creta, este cea mai veche lege constituțională grecească păstrată. Subiectul ei este cetatea. Conținutul ei este limitarea puterii: magistratul suprem nu poate fi reales timp de zece ani.","Cinci: colonizarea. Între secolele opt și șase înainte de Hristos, întemeierea de noi cetăți, între care Histria, colonie a Miletului, presupunea alegerea deliberată a legilor.","Șase: cuvântul public. Isonomia, egalitatea în fața legii, și isegoria, dreptul egal la cuvânt, presupun că orice afirmație poate fi contestată prin argumente."],"cards":[{"c":1,"n":"01","h":"Fragmentarea geografică","p":"Relief și insule: comunități mici, autonome, fără o lege imperială unică."},{"c":2,"n":"02","h":"O religie fără dogmă","p":"Fără carte sacră, fără castă sacerdotală. Preoțiile: magistraturi civice."},{"c":3,"n":"03","h":"Armata cetățenilor","p":"Falanga hoplitică. „Revoluția hoplitică” rămâne o ipoteză disputată."},{"c":4,"n":"04","h":"Legea scrisă și publică","p":"Dreros, Creta, cca 650–600 î.Hr.: magistratul suprem nu poate fi reales 10 ani.","img":"m1_lege2"},{"c":5,"n":"05","h":"Colonizarea","p":"Sec. VIII–VI î.Hr. Histria, colonie a Miletului: legi alese deliberat."},{"c":6,"n":"06","h":"Cuvântul public","p":"isonomia (egalitate în fața legii) · isēgoria (drept egal la cuvânt)"}]},{"id":"1.4","type":"thesis","k":"04 · Anaximandru din Milet","img":"m1_cosmos","n":["Aceeași structură apare și în felul în care grecii gândesc natura.","La Milet, în secolul al șaselea înainte de Hristos, Anaximandru descrie ordinea naturii în limbajul justiției: lucrurile își plătesc unele altora pentru nedreptate, după rânduiala timpului.","Cosmosul este gândit ca o cetate supusă legii, nu ca domeniul unui stăpân divin."],"big":{"c":1,"t":"Lucrurile „își plătesc” unele altora pentru nedreptate, după *rânduiala* timpului."},"r":"Anaximandru, fr. B1 DK · sec. VI î.Hr.","sub":{"c":2,"t":"Cosmosul, gândit ca o cetate supusă legii, nu ca domeniul unui stăpân divin."}},{"id":"1.5","type":"diagram","d":"athens","k":"05 · Atena, sec. V–IV î.Hr.","t":"Cetățeanul *participă*","img":"m1_atena","n":["În secolele cinci și patru înainte de Hristos, democrația ateniană funcționa prin câteva instituții.","Adunarea, ekklēsia. Sfatul celor cinci sute, boulē. Tribunalele cu jurii trase la sorți, dikastēria. Și magistraturi ocupate, în majoritate, tot prin tragere la sorți.","Pentru Aristotel, cetățeanul este cel care participă la judecată și la conducere.","Retragerea în viața privată era depreciată. Cuvântul idiōtēs desemna omul care nu ia parte la treburile publice."],"inst":[{"c":1,"h":"ekklēsia","p":"Adunarea cetățenilor"},{"c":1,"h":"boulē","p":"Sfatul celor 500"},{"c":1,"h":"dikastēria","p":"Tribunale cu jurii trase la sorți"},{"c":1,"h":"magistraturi","p":"ocupate majoritar prin tragere la sorți"}],"center":{"c":2,"h":"Cetățeanul","p":"cel care participă la judecată și la conducere","r":"Aristotel, Politica III.1, 1275a22–23"},"foot":{"c":3,"h":"idiōtēs","p":"omul care nu ia parte la treburile publice","r":"Tucidide II.40"}},{"id":"1.6","type":"concept","k":"06 · Legea pusă sub întrebare","t":"Ce fac oamenii, oamenii pot *critica*","img":"m1_sofisti","mark":{"x":86,"y":22,"w":12,"h":38,"l":"citim nomos"},"n":["Din moment ce legile erau votate și modificate de oameni, ele puteau fi și criticate de oameni.","Sofiștii susțin că legile sunt convenții, nomos, nu expresii ale naturii, physis.","Herodot atribuie unor nobili perși prima dezbatere comparativă asupra constituțiilor.","Platon și Aristotel răspund acestei crize. Aristotel, metic la Atena, adică străin cu drept de ședere, compară constituțiile a peste o sută de cetăți.","Explicația are însă limite. Alfabetul și o parte din cunoștințele astronomice și matematice sunt preluate din Orientul Apropiat.","Iar participarea politică era rezervată bărbaților adulți, fii de cetățeni. Femeile, sclavii și meticii, adică majoritatea locuitorilor, erau excluși."],"notes":[{"c":1,"n":"01","h":"Sofiștii","p":"legile sunt nomos (convenții), nu physis"},{"c":2,"n":"02","h":"Herodot","p":"prima dezbatere comparativă asupra constituțiilor","r":"Istorii III.80–82"},{"c":3,"n":"03","h":"Platon și Aristotel","p":"răspund crizei; Aristotel compară peste 100 de constituții"}],"limit":{"c":4,"h":"Limitele explicației","items":[{"c":4,"t":"Alfabetul și o parte din astronomie și matematică vin din Orientul Apropiat (Burkert, West)."},{"c":5,"t":"Femeile, sclavii și meticii, majoritatea locuitorilor, erau excluși de la participare."}]}},{"id":"1.7","type":"timeline","k":"07 · De la antici la moderni","t":"Aceeași întrebare, *trei* crize","n":["Problema este reluată în trei momente de criză.","Hobbes scrie Leviathan în 1651, după războiul civil englez și după execuția regelui Carol întâi, în 1649.","Rousseau scrie Discursul asupra inegalității în 1755, ca răspuns la un concurs al Academiei din Dijon.","După O teorie a dreptății a lui Rawls, din 1971, dezbaterea se mută de la întrebarea cum este omul la întrebarea ce își datorează individul și comunitatea unul altuia."],"items":[{"c":0,"y":"sec. IV î.Hr.","h":"Aristotel, Politica","p":"cetatea și natura omului"},{"c":1,"y":"1642–1651","h":"Războiul civil englez","p":"1649: execuția lui Carol I"},{"c":1,"y":"1651","h":"Hobbes, Leviathan","p":"scris în exil, la Paris"},{"c":2,"y":"1755","h":"Rousseau, Discursul asupra inegalității","p":"concursul Academiei din Dijon"},{"c":3,"y":"1971","h":"Rawls, O teorie a dreptății","p":"„Ce își datorează individul și comunitatea?”"}]},{"id":"1.8","type":"triptych","k":"08 · Teorii relevante","t":"Împlinește, constrânge sau *transformă*?","n":["Teoriile clasice dau trei răspunsuri distincte.","Pentru Aristotel, comunitatea împlinește natura umană.","Pentru Hobbes, ea este construită împotriva dispozițiilor naturale ale omului.","Pentru Rousseau, ea o transformă.","Dezbaterea contemporană reformulează problema în termenii raportului dintre autonomie și datorie civică. Le luăm pe rând."],"cols":[{"c":1,"w":"împlinește","h":"Aristotel","p":"teza naturii","img":"m1_agora"},{"c":2,"w":"construită împotriva","h":"Hobbes","p":"teza artificiului","img":"m1_pact"},{"c":3,"w":"transformă","h":"Rousseau","p":"teza transformării","img":"m1_dans"}],"foot":{"c":4,"t":"Azi: autonomie și datorie civică (liberalism · comunitarism · republicanism civic)"}},{"id":"1.9","type":"concept","k":"09 · Aristotel, Politica I.2","t":"Omul, prin natură, o *ființă politică*","img":"m1_aristotel","n":["Începem cu Aristotel, în Politica, cartea întâi.","Aristotel aplică politicii un naturalism teleologic. Natura unui lucru este forma lui deplin realizată, scopul, telos, spre care tinde.","Comunitățile se succed: de la casă la sat și de la sat la cetate. Cetatea este singura comunitate care își ajunge sieși. Grecii numeau asta autarkeia.","Cetatea apare pentru supraviețuire, dar există pentru viața bună.","De aici teza: omul este prin natură o ființă politică, zōon politikon.","Cetatea este anterioară individului prin natură, nu în timp. Așa cum întregul este anterior părții: o mână desprinsă de corp este mână doar cu numele."],"steps":[{"c":2,"h":"casa"},{"c":2,"h":"satul"},{"c":2,"h":"cetatea","p":"autarkeia"}],"stepsNote":{"c":3,"t":"apare pentru supraviețuire · există pentru *viața bună*"},"notes":[{"c":1,"n":"01","h":"telos","p":"natura unui lucru = forma lui deplin realizată"},{"c":4,"n":"02","h":"zōon politikon","p":"omul este prin natură o ființă politică"},{"c":5,"n":"03","h":"Întregul înaintea părții","p":"o mână desprinsă de corp e mână doar cu numele"}]},{"id":"1.10","type":"procon","k":"10 · Teza naturii, cântărită","t":"Aristotel: *pentru* și împotrivă","n":["Ce argumente sprijină teza?","Argumentul logosului. Animalele au voce, phōnē, prin care semnalează plăcerea și durerea. Omul are logos, prin care deliberează asupra folositorului și dăunătorului, a dreptății și nedreptății. Dacă natura nu face nimic în zadar, această capacitate presupune o comunitate în care să fie exercitată.","Argumentul insuficienței. Individul izolat nu își ajunge sieși. Cine nu poate trăi în comunitate, sau nu are nevoie de ea, este fie fiară, fie zeu.","Argumentul diferenței de grad. Albinele trăiesc și ele în grup, dar omul este politic într-un grad mai înalt, pentru că numai el deliberează despre just și injust.","Și obiecțiile? Premisa teleologică, natura nu face nimic în zadar, nu mai este acceptată de biologia evoluționistă. Fără ea, faptul că omul poate delibera în comun nu înseamnă că este destinat să o facă.","Același naturalism legitimează ierarhii: sclavia prin natură și excluderea femeilor din cetățenie. Apelul la natură poate consfinți o ordine socială contingentă, adică una care putea fi și altfel.","În sfârșit, anterioritatea cetății față de individ poate fi folosită pentru a subordona individul colectivității."],"pro":[{"c":1,"h":"Argumentul logosului","p":"phōnē semnalează plăcerea și durerea; logos deliberează despre just și injust.","r":"1253a7–18"},{"c":2,"h":"Argumentul insuficienței","p":"Cine nu are nevoie de comunitate e „fie fiară, fie zeu”.","r":"1253a27–29"},{"c":3,"h":"Diferența de grad","p":"Albinele trăiesc în grup; doar omul deliberează despre just și injust."}],"con":[{"c":4,"h":"Premisa teleologică","p":"„Natura nu face nimic în zadar” nu mai e acceptată de biologia evoluționistă."},{"c":5,"h":"Ierarhii „naturale”","p":"Sclavia „prin natură” și excluderea femeilor.","r":"Politica I.4–7"},{"c":6,"h":"Subordonarea individului","p":"Anterioritatea cetății poate justifica supunerea față de colectivitate."}]},{"id":"1.11","type":"media","k":"11 · Hobbes, Leviathan (1651)","t":"Starea naturală, un *experiment* de gândire","video":"v_leviathan","img":"m1_hobbes","n":["Al doilea răspuns vine din mijlocul unui război civil.","Thomas Hobbes scrie Leviathan în 1651, în exil la Paris, după prăbușirea autorității statului. Mai devreme publicase De Cive, în 1642.","Starea naturală nu este o epocă istorică. Este o ipoteză, un experiment de gândire: cum ar trăi oamenii în absența unei puteri comune?","Răspunsul lui Hobbes: într-un război al fiecăruia împotriva fiecăruia.","Ordinea politică nu este dată de natură. Ea este instituită printr-un pact, prin care oamenii autorizează un suveran să garanteze pacea."],"notes":[{"c":1,"n":"01","h":"Context","p":"exil la Paris; De Cive (1642), Leviathan (1651), cap. XIII–XVII"},{"c":2,"n":"02","h":"Starea naturală","p":"o ipoteză: viața fără o putere comună"},{"c":3,"n":"03","h":"„Războiul fiecăruia împotriva fiecăruia”","p":""},{"c":4,"n":"04","h":"Pactul","p":"oamenii autorizează un suveran să garanteze pacea"}]},{"id":"1.12","type":"procon","k":"12 · Teza artificiului, cântărită","t":"Hobbes: *pentru* și împotrivă","img":"m1_usa","n":["Hobbes își sprijină teza pe patru argumente.","Argumentul egalității. Oamenii sunt aproximativ egali în capacitatea de a se ucide unii pe alții, prin viclenie sau prin alianțe. Nimeni nu este în siguranță.","Trei cauze ale conflictului: competiția, pentru câștig; neîncrederea, pentru siguranță; gloria, pentru reputație.","Argumentul strategic. Fără o garanție a regulilor, atacul preventiv este rațional chiar și pentru oamenii moderați. Teza nu presupune că oamenii sunt răi, ci doar nesiguri.","Argumentul experienței. Omul se înarmează când pleacă la drum și își încuie ușa noaptea. Prin aceste gesturi își spune deja părerea despre semeni.","Obiecțiile sunt la fel de serioase. Problema încrederii: dacă în starea naturală nimeni nu are motive să se încreadă în altul, cum poate fi încheiat și respectat pactul?","Rousseau îi reproșează lui Hobbes că atribuie omului natural pasiuni, lăcomia și orgoliul, dobândite de fapt în societate.","Și riscul invers: un suveran absolut, menit să înlăture frica reciprocă, devine el însuși o sursă de teamă. Locke observă că nu e rațional să te ferești de dihori și de vulpi ca să te lași devorat de un leu."],"pro":[{"c":1,"h":"Egalitatea","p":"Oricine poate ucide pe oricine, prin viclenie sau alianță."},{"c":2,"h":"Trei cauze ale conflictului","p":"competiția (câștig) · neîncrederea (siguranță) · gloria (reputație)"},{"c":3,"h":"Argumentul strategic","p":"Fără garanții, atacul preventiv e rațional. Oamenii nu sunt răi, ci nesiguri."},{"c":4,"h":"Experiența","p":"Te înarmezi la drum, îți încui ușa noaptea.","r":"cap. XIII"}],"con":[{"c":5,"h":"Problema încrederii","p":"Fără încredere, cum se încheie și se respectă pactul?"},{"c":6,"h":"Critica lui Rousseau","p":"Lăcomia și orgoliul sunt dobândite în societate."},{"c":7,"h":"Riscul invers","p":"Dihori și vulpi contra unui leu.","r":"Locke, Al doilea tratat, § 93"}]},{"id":"1.13","type":"concept","k":"13 · Rousseau, Discursul (1755)","t":"Viața în comun nu exprimă natura omului, ci o *modifică*","img":"m1_rousseau","mark":{"x":44,"y":46,"w":14,"h":34,"l":"citim omul natural"},"n":["Al treilea răspuns: Jean-Jacques Rousseau, Discurs asupra originii și fundamentelor inegalității dintre oameni, 1755.","Rousseau răspunde la întrebarea Academiei din Dijon despre originea inegalității. Îl citește critic pe Hobbes și reconstruiește, ipotetic, istoria speciei.","Omul natural este solitar, are puține nevoi și nu este nici bun, nici rău în sens moral.","El are trei dispoziții: iubirea de sine, amour de soi; mila, pitié; și perfectibilitatea, adică puterea de a se transforma.","Concluzia: viața în comun nu exprimă natura omului. O modifică."],"notes":[{"c":2,"n":"01","h":"Omul natural","p":"solitar, cu puține nevoi, nici bun, nici rău în sens moral"},{"c":3,"n":"02","h":"amour de soi · pitié","p":"iubirea de sine · mila"},{"c":3,"n":"03","h":"perfectibilitatea","p":"capacitatea de a se transforma"}]},{"id":"1.14","type":"procon","k":"14 · Teza transformării, cântărită","t":"Rousseau: *pentru* și împotrivă","n":["Argumentele pentru teza lui Rousseau sunt trei.","Critica metodologică. Starea naturală a predecesorilor este o proiecție a omului social. Trebuie separat ce este natural de ce este dobândit.","Geneza amorului propriu. Oamenii care trăiesc aproape încep să se compare. Iubirea de sine devine amour-propre: dorința de a fi preferat. Mecanismul explică rivalitatea fără să o pună pe seama naturii.","Distincția inegalităților. Inegalitatea naturală, de vârstă sau de forță, se deosebește de inegalitatea morală sau politică, de avere sau de rang. Aceasta din urmă e instituită prin convenție, începând cu proprietatea.","Obiecțiile. Starea naturală este explicit ipotetică: Rousseau începe prin a lăsa deoparte faptele. Reconstrucția nu poate fi testată istoric.","Omul natural solitar este contrazis de primatologie și antropologie: speciile apropiate și grupurile umane cunoscute trăiesc în grup.","Amorul propriu nu este neapărat coruptor. Frederick Neuhouser arată că poate lua forme benigne, cum ar fi nevoia de recunoaștere egală.","Și o precizare: Rousseau nu propune întoarcerea în starea naturală. Expresia bunul sălbatic nu îi aparține. Problema lui devine alta: în ce condiții poate fi legitimă asocierea? O tratează în Contractul social, în 1762."],"pro":[{"c":1,"h":"Critica metodologică","p":"Starea naturală a predecesorilor e o proiecție a omului social."},{"c":2,"h":"Geneza amorului propriu","p":"Comparația transformă amour de soi în amour-propre: dorința de a fi preferat."},{"c":3,"h":"Două inegalități","p":"naturală (vârstă, forță) · morală sau politică (avere, rang), instituită prin convenție"}],"con":[{"c":4,"h":"Explicit ipotetică","p":"„Să lăsăm deoparte faptele”: reconstrucția nu se poate testa."},{"c":5,"h":"Primatologia și antropologia","p":"Speciile apropiate și grupurile umane trăiesc în grup."},{"c":6,"h":"Amorul propriu benign","p":"Nevoia de recunoaștere egală.","r":"Neuhouser, 2014"}],"foot":{"c":7,"t":"„Bunul sălbatic” nu e expresia lui Rousseau. Întrebarea lui devine legitimitatea asocierii: *Contractul social* (1762)."}},{"id":"1.15","type":"ex","ex":"sort","k":"Exercițiu · Aplică","t":"Cine ar spune *asta*?","n":["Acum e rândul tău. Iată nouă afirmații. Pentru fiecare, alege gânditorul care ar putea-o susține.","Selectează o afirmație, apoi coloana potrivită. Primești imediat explicația."],"colsEx":["Aristotel","Hobbes","Rousseau"],"items":[{"t":"Cine nu are nevoie de cetate este fie fiară, fie zeu.","a":0,"f":"Argumentul insuficienței (Politica I.2): omul izolat nu își ajunge sieși."},{"t":"Cetatea apare pentru supraviețuire, dar există pentru viața bună.","a":0,"f":"Teza naturii: scopul (telos) cetății este viața bună."},{"t":"Doar omul deliberează despre just și injust; de aceea e politic într-un grad mai înalt decât albinele.","a":0,"f":"Argumentul diferenței de grad, sprijinit pe logos."},{"t":"Fără o garanție a regulilor, chiar și un om moderat are motive să atace primul.","a":1,"f":"Argumentul strategic: oamenii nu sunt răi, ci nesiguri."},{"t":"Când îți încui ușa noaptea, spui deja ce crezi despre semenii tăi.","a":1,"f":"Argumentul experienței (Leviathan, cap. XIII)."},{"t":"Pacea cere un suveran autorizat printr-un pact.","a":1,"f":"Teza artificiului: ordinea politică e instituită, nu dată de natură."},{"t":"Ce numim „natura umană” e adesea omul social proiectat înapoi.","a":2,"f":"Critica metodologică: trebuie separat naturalul de dobândit."},{"t":"Comparația cu ceilalți naște dorința de a fi preferat.","a":2,"f":"Geneza amorului propriu (amour-propre)."},{"t":"Inegalitatea de avere și de rang e instituită prin convenție, începând cu proprietatea.","a":2,"f":"Distincția dintre inegalitatea naturală și cea morală sau politică."}]},{"id":"1.16","type":"diagram","d":"axes2","k":"15 · După 1971","t":"Pe ce temei se justifică *regulile* comune?","n":["După 1971, întrebarea se schimbă: pe ce temei se justifică regulile vieții în comun?","Pe principii acceptabile pentru oricine, indiferent de ce crede despre viața bună? Sau pe un bine comun împărtășit?","Dezbaterea are două axe. Prima opune libertatea ca sferă privată protejată libertății ca participare. Benjamin Constant, în 1819, le numea libertatea modernilor și libertatea anticilor.","A doua axă privește raportul dintre individ și comunitate. Charles Taylor arată că ea conține, de fapt, două întrebări.","Una ontologică: cum se formează persoana? Și una normativă: ce are prioritate morală?","Atenție: cine susține că persoana este formată de comunitate nu susține automat că scopurile colective au prioritate față de drepturile individuale."],"q2":[{"c":1,"t":"principii acceptabile pentru oricine"},{"c":1,"t":"un bine comun împărtășit"}],"ax1":{"c":2,"a":"libertatea modernilor","ap":"sferă privată protejată","b":"libertatea anticilor","bp":"participare","r":"Constant, 1819"},"ax2":{"c":3,"a":"ontologic","ap":"cum se formează persoana?","b":"normativ","bp":"ce are prioritate morală?","r":"Taylor, 1989","c2":4},"warn":{"c":5,"t":"Persoana formată de comunitate ≠ prioritatea scopurilor colective asupra drepturilor."}},{"id":"1.17","type":"procon","k":"16 · Viziunea liberală (Rawls)","t":"Dreptul are prioritate față de *bine*","video":"v_val","img":"m1_val","n":["Prima viziune este cea liberală, reprezentată de John Rawls.","Persoanele sunt libere și egale, capabile să își examineze și să își revizuiască concepția despre bine. Dreptul are prioritate față de bine. Statul rămâne neutru față de concepțiile despre viața bună.","Iar dezacordul rezonabil asupra binelui este o trăsătură permanentă a unei societăți libere.","Argumentul: într-o societate pluralistă, singurele reguli acceptabile pentru toți sunt cele care nu presupun o anumită concepție despre bine. Ele ar fi alese în spatele unui văl de ignoranță, fără să știi ce loc vei ocupa tu în societate.","Concepția despre persoană este, spune Rawls, politică, nu metafizică. Nu descrie tot ce suntem, ci felul în care ne tratăm reciproc ca cetățeni.","Criticii răspund. Michael Sandel: persoana gândită fără atașamente constitutive nu corespunde niciunui om real. Iar neutralitatea este iluzorie, pentru că orice ordine politică favorizează anumite moduri de viață.","Charles Taylor: capacitatea de a alege se formează doar într-un anumit tip de societate, pe care liberalismul o presupune fără să o susțină. Și o cooperare întemeiată doar pe avantaj reciproc explică greu solidaritatea."],"thesis":[{"c":1,"t":"persoane libere și egale · dreptul înaintea binelui · stat neutru"},{"c":2,"t":"dezacordul rezonabil e permanent"}],"pro":[{"c":3,"h":"Vălul de ignoranță","p":"Reguli acceptabile pentru toți, alese fără să-ți știi locul."},{"c":4,"h":"„Politică, nu metafizică”","p":"Cum ne tratăm ca cetățeni, nu tot ce suntem.","r":"Rawls, 1985"}],"con":[{"c":5,"h":"Persoana fără atașamente","p":"Nu corespunde niciunui om real; neutralitatea e iluzorie.","r":"Sandel, 1982; 1996"},{"c":6,"h":"Capacitatea de a alege","p":"Se formează într-o societate pe care liberalismul o presupune.","r":"Taylor, 1985"}]},{"id":"1.18","type":"procon","k":"17 · Viziunea comunitaristă","t":"Din ce *poveste* fac parte?","img":"m1_comunitate","n":["A doua viziune este numită comunitaristă: MacIntyre, Sandel, Taylor, Walzer.","Eticheta a fost dată de comentatori. Autorii au respins-o sau au acceptat-o cu rezerve. Este o viziune, nu o școală.","Tezele: identitatea se formează prin atașamente nealese, familia, limba, tradiția. Unele obligații, ca loialitatea și solidaritatea, provin din apartenență, nu din consimțământ. Iar viața în comun presupune un bine împărtășit, care nu se reduce la suma intereselor individuale.","Argumentul lui Alasdair MacIntyre: întrebarea ce trebuie să fac presupune o întrebare anterioară, din ce poveste fac parte? Criteriile alegerii nu sunt create de individ, ci primite într-o practică comună.","Viziunea explică obligațiile de loialitate, pe care modelul contractual le reconstruiește cu dificultate.","Obiecții: fiecare persoană aparține mai multor comunități, iar cerințele lor pot intra în conflict.","Un bine comun stabilit de majoritate sau de tradiție poate fi impus celor care nu îl împărtășesc, observă Amy Gutmann. Iar familia, comunitatea cea mai valorizată, poate fi locul inegalității dintre femei și bărbați, arată Susan Moller Okin.","Și dacă normele vin din tradiție, cum mai poți critica o tradiție nedreaptă? Michael Walzer răspunde: critica se face din interior, cu resursele morale ale tradiției însăși."],"thesis":[{"c":1,"t":"o viziune, nu o școală"},{"c":2,"t":"atașamente nealese · obligații din apartenență · un bine împărtășit"}],"pro":[{"c":3,"h":"„Din ce poveste fac parte?”","p":"Criteriile alegerii sunt primite într-o practică comună.","r":"MacIntyre, 1981"},{"c":4,"h":"Loialitatea","p":"Explică obligații pe care contractul le reconstruiește greu."}],"con":[{"c":5,"h":"Mai multe comunități","p":"Cerințele lor pot intra în conflict."},{"c":6,"h":"Riscul impunerii","p":"Binele majorității impus celorlalți; inegalitatea în familie.","r":"Gutmann, 1985; Okin, 1989"},{"c":7,"h":"Critica din interior","p":"Cu resursele morale ale tradiției însăși.","r":"Walzer, 1987"}]},{"id":"1.19","type":"procon","k":"18 · Republicanismul civic","t":"Libertatea ca *non-dominație*","img":"m1_adunare","n":["A treia viziune este republicanismul civic, cu Philip Pettit și Quentin Skinner.","Libertatea este non-dominație: să nu depinzi de voința arbitrară a altuia, chiar dacă acesta nu intervine efectiv.","O lege nearbitrară nu restrânge libertatea, ci o constituie. Libertatea se păstrează prin participarea și vigilența cetățenilor, iar deciziile publice trebuie să poată fi contestate de cei afectați. Linia istorică trece prin Machiavelli și Rousseau.","Gândește-te la un sclav cu un stăpân binevoitor. Stăpânul nu intervine, deci, după criteriul neintervenției, sclavul nu este constrâns. Și totuși nu este liber, pentru că depinde de bunăvoința altuia.","Viziunea leagă astfel autonomia individului de existența unei comunități de cetățeni activi.","Obiecții. Participarea civică intensă este greu de cerut în societăți mari, în care viața privată este prețuită, cum observa Constant.","Poziția este instabilă: dacă virtutea civică este doar un mijloc, viziunea se apropie de liberalism; dacă este un bine în sine, de comunitarism. Și criteriul non-dominației depinde de cine stabilește ce putere este arbitrară."],"thesis":[{"c":1,"t":"să nu depinzi de voința arbitrară a altuia"},{"c":2,"t":"legea nearbitrară constituie libertatea · participare și contestare"}],"pro":[{"c":3,"h":"Sclavul cu stăpân binevoitor","p":"Nimeni nu intervine, și totuși nu e liber."},{"c":4,"h":"Autonomie și cetățeni activi","p":"Libertatea individului depinde de o comunitate vigilentă."}],"con":[{"c":5,"h":"Societăți mari","p":"Participarea intensă e greu de cerut.","r":"Constant"},{"c":6,"h":"Poziție instabilă","p":"Mijloc → liberalism; bine în sine → comunitarism.","r":"Patten, 1996"}]},{"id":"1.20","type":"table","k":"19 · Trei viziuni, față în față","t":"Autonomie sau *datorie* civică?","n":["Pune cele trei viziuni una lângă alta.","Valoarea centrală: autonomia, pentru liberali; libertatea ca non-dominație, pentru republicani; binele comun, pentru comunitariști.","Persoana: capabilă să își revizuiască scopurile; cetățean activ; constituită de atașamente.","Statul: neutru față de concepțiile despre bine; garant al non-dominației; promotor al unui bine comun.","Datoria civică: respectarea regulilor echitabile; condiție a libertății; parte a identității.","Și dificultatea principală a fiecăreia: persoana abstractă; poziția instabilă; riscul opresiunii."],"head":["","Liberalismul","Republicanismul civic","Comunitarismul"],"rows":[{"c":1,"cells":["Valoarea centrală","autonomia","libertatea ca non-dominație","binele comun"]},{"c":2,"cells":["Persoana","capabilă să își revizuiască scopurile","cetățean activ","constituită de atașamente"]},{"c":3,"cells":["Statul","neutru față de concepțiile despre bine","garant al non-dominației","promovează un bine comun"]},{"c":4,"cells":["Datoria civică","respectarea regulilor echitabile","condiție a libertății","parte a identității"]},{"c":5,"cells":["Dificultatea principală","persoana abstractă","poziție instabilă","riscul opresiunii"]}]},{"id":"1.21","type":"ex","ex":"dilemma","k":"Exercițiu · Aplică","t":"Trei voci în *consiliu*","n":["Un consiliu local imaginar discută dacă tinerii din cartier ar trebui să facă douăzeci de ore de voluntariat pe an.","Trei participanți iau cuvântul. Recunoaște, pentru fiecare, viziunea din care vorbește."],"scene":"Consiliul unui cartier imaginar discută o propunere: 20 de ore de voluntariat pe an pentru tinerii din cartier.","opts":["liberală","comunitaristă","republicană"],"items":[{"who":"Ana","t":"„Statul nu trebuie să-mi spună ce viață bună să aleg. Dacă vrea reguli, să fie echitabile pentru toți, oricare ar fi convingerile lor.”","a":0,"f":"Neutralitatea statului și reguli echitabile pentru oricine: viziunea liberală."},{"who":"Mihai","t":"„Cartierul ne-a format. Le datorăm ceva celor cu care împărțim strada, chiar dacă n-am semnat niciun contract.”","a":1,"f":"Obligații din apartenență, nu din consimțământ: viziunea comunitaristă."},{"who":"Irina","t":"„Accept regula doar dacă o putem discuta și contesta în consiliu. Altfel depindem de voința arbitrară a câtorva.”","a":2,"f":"Non-dominația și contestabilitatea deciziilor publice: republicanismul civic."}]},{"id":"1.22","type":"stats","k":"20 · Ce spun cercetările","t":"Cercetările nu tranșează disputa, dar îi fixează *limitele*","n":["Ce spun cercetările empirice? Nu tranșează disputa, dar îi fixează limitele.","Dispoziția de a ajuta apare la copiii de optsprezece luni și nu depinde de recompensă.","Cooperarea între străini se erodează în absența sancțiunilor.","Normele de echitate variază între culturi.","Relațiile sociale sunt asociate cu o probabilitate de supraviețuire cu aproximativ cincizeci la sută mai mare.","Comunitățile se pot autoorganiza, dar numai în anumite condiții, arată Elinor Ostrom.","Concluzia: nicio teorie nu poate susține credibil nici că omul este exclusiv egoist, nici că el cooperează de la sine, oricând și oricum."],"stats":[{"c":1,"v":"18 luni","p":"vârsta la care apare dispoziția de a ajuta, fără recompensă","r":"Warneken și Tomasello, 2006"},{"c":2,"v":"fără sancțiuni","p":"cooperarea între străini se erodează","r":"Fehr și Gächter, 2002"},{"c":3,"v":"între culturi","p":"normele de echitate variază","r":"Henrich et al., 2001"},{"c":4,"v":"≈ +50%","p":"probabilitate de supraviețuire asociată relațiilor sociale","r":"Holt-Lunstad et al., 2010"},{"c":5,"v":"în anumite condiții","p":"comunitățile se pot autoorganiza","r":"Ostrom, 1990"}],"foot":{"c":6,"t":"Nici *exclusiv egoist*, nici cooperant de la sine, oricând și oricum."}},{"id":"1.23","type":"conclusion","k":"Concluzie","t":"Natura oferă capacitatea, nu și *forma*","n":["Să strângem firele. Clasicii formulează problema în trei variante: comunitatea împlinește, constrânge sau transformă natura umană.","Fiecare variantă lasă o problemă deschisă. Cine aparține cetății, la Aristotel. Care sunt limitele puterii suverane, la Hobbes. În ce condiții este legitimă asocierea, la Rousseau.","Filosofia contemporană mută dezbaterea de la descrierea omului la justificarea regulilor comune și o organizează între autonomie și datorie civică.","Concluzia de lucru: natura oferă capacitatea vieții în comun, nu și forma ei. Forma este instituită prin reguli și instituții.","Rămâne disputată trecerea de la descriere la normă: din ceea ce este omul nu decurge automat cum trebuie organizată puterea.","Teza modulului: concepția despre natura umană determină ce fel de putere politică socotim necesară.","De aici pornește modulul doi: dacă oamenii au nevoie de o putere comună, cum trebuie organizată această putere?"],"open":[{"c":1,"h":"Aristotel","p":"cine aparține cetății?"},{"c":1,"h":"Hobbes","p":"care sunt limitele puterii suverane?"},{"c":1,"h":"Rousseau","p":"când e legitimă asocierea?"}],"work":{"c":3,"t":"Natura oferă capacitatea vieții în comun, nu și forma ei."},"big":{"c":5,"t":"Concepția despre natura umană determină ce fel de *putere politică* socotim necesară."},"next":{"c":6,"t":"Dacă oamenii au nevoie de o putere comună, cum trebuie organizată această putere?","m":"Modulul 02"}},{"id":"1.24","type":"quiz","k":"Verificare","t":"Cinci întrebări, cu *explicații*","n":["Verifică-te. Cinci întrebări, cu explicații după fiecare răspuns. Nu se notează: contează să înțelegi de ce."],"qs":[{"q":"Ce înseamnă, la Aristotel, că cetatea este anterioară individului „prin natură”?","o":["Cetatea a apărut, în timp, înaintea oamenilor.","Ca întregul față de parte: individul se realizează deplin doar în cetate.","Legile cetății sunt mai vechi decât familia.","Individul nu are niciun drept în fața cetății."],"a":1,"f":"Anterioritatea e logică, nu cronologică: o mână desprinsă de corp e mână doar cu numele."},{"q":"Starea naturală, la Hobbes, este…","o":["o epocă istorică bine documentată","un experiment de gândire: viața în absența unei puteri comune","o stare de pace firească","descrierea triburilor din America"],"a":1,"f":"Hobbes o tratează ca ipoteză: ce s-ar întâmpla fără o putere care să garanteze regulile."},{"q":"Care afirmație îi aparține lui Rousseau?","o":["Omul natural e solitar și nu e nici bun, nici rău în sens moral.","Viața fără putere comună e un război al fiecăruia împotriva fiecăruia.","Omul e prin natură o ființă politică.","Trebuie să ne întoarcem la „bunul sălbatic”."],"a":0,"f":"Rousseau reconstruiește ipotetic omul natural. Expresia „bunul sălbatic” nu îi aparține, iar el nu propune întoarcerea."},{"q":"Un sclav are un stăpân binevoitor care nu intervine niciodată. Ce viziune spune că, totuși, sclavul nu e liber?","o":["Viziunea liberală","Republicanismul civic","Comunitarismul","Teza artificiului (Hobbes)"],"a":1,"f":"Libertatea ca non-dominație: dependența de voința arbitrară a altuia e deja lipsă de libertate."},{"q":"Ce arată cercetările empirice despre cooperare?","o":["Omul este exclusiv egoist.","Omul cooperează de la sine, oricând și oricum.","Cooperarea există, dar depinde de condiții, de exemplu de sancțiuni.","Normele de echitate sunt aceleași în toate culturile."],"a":2,"f":"Dispoziția de a ajuta apare devreme, dar cooperarea între străini se erodează fără sancțiuni, iar normele variază între culturi."}]},{"id":"1.25","type":"ws","ws":"m1","k":"Fișă de lucru · Aplică","t":"Fișa ta de *lucru*","n":["Acum completezi fișa de lucru a modulului.","Are trei etape, ca modulul, și un scurt feedback. Răspunde pe scurt, în unul sau două rânduri.","Dacă nu-ți amintești un răspuns, deschide indiciul: te duce la ecranul potrivit. Poți completa fișa și pe parcurs, din butonul Fișa, din bara de jos.","Fișa se salvează singură. La final, descarc-o și trimite-o profesorului tău."]},{"id":"1.26","type":"biblio","k":"Resurse","t":"Bibliografia *modulului*","n":["Aici găsești bibliografia modulului: surse primare, lucrări didactice și studii. O poți deschide oricând din butonul Resurse."],"bib":"m1"}]},{"id":"m2","num":"02","title":"Cine conduce și în *folosul* cui","sub":"Regimurile politice","q":"Cum trebuie organizată puterea comună, odată ce am admis că avem nevoie de ea?","thesis":"Un regim bun servește binele comun și are puterea limitată.","cover":"m2_cover","screens":[{"id":"2.0","type":"cover","img":"m2_cover","mark":{"x":44,"y":18,"w":11,"h":62,"l":"citim puterea"},"n":["Modulul doi. Cine conduce și în folosul cui.","Am admis, în primul modul, că oamenii au nevoie de o putere comună. Întrebarea de acum: cum trebuie organizată această putere?","Teza la care ajungem este simplă de formulat și greu de realizat: un regim bun servește binele comun și are puterea limitată.","Vei compara clasificările lui Herodot, Platon și Aristotel, vei cântări monarhia, democrația, teocrația și anarhia, și vei vedea de ce utopia poate deveni distopie."],"goals":[{"c":3,"t":"Deosebești regimul politic de forma de guvernământ și de structura de stat."},{"c":3,"t":"Explici criteriile lui Herodot, Platon și Aristotel și le aplici pe cazuri."},{"c":3,"t":"Cântărești argumentele pentru și contra monarhiei, democrației, teocrației și anarhismului."},{"c":3,"t":"Explici legătura dintre utopie, distopie și totalitarism."}]},{"id":"2.1","type":"table","k":"01 · Delimitarea noțiunii","t":"Regimul politic: *cum* se exercită puterea","n":["Regimul politic este modul în care este organizată și exercitată puterea într-o comunitate: cine decide, în ce limite și cu ce justificare. Grecii îl numeau politeia.","Noțiunea trebuie distinsă de alte două, cu care este des confundată.","Forma de guvernământ stabilește cine este șeful statului: un monarh ereditar sau un președinte ales. România este republică.","Structura de stat arată cum este împărțită puterea pe teritoriu: un singur centru sau state federate. România este stat național, unitar.","Regimul politic arată cum se exercită puterea și ce o limitează. Constituția României vorbește despre stat de drept, democratic.","Distincția previne o confuzie frecventă. Monarhia și republica sunt forme de guvernământ, nu regimuri. O monarhie poate fi democratică, cum este Regatul Unit, iar o republică poate fi autoritară."],"lead":{"c":0,"t":"cine decide · în ce limite · cu ce justificare"},"head":["Criteriul","Ce stabilește","România (Constituția, art. 1)"],"rows":[{"c":2,"cells":["Forma de guvernământ","cine este șeful statului: monarh ereditar sau președinte ales","republică"]},{"c":3,"cells":["Structura de stat","cum e împărțită puterea pe teritoriu: un centru sau state federate","stat național, unitar"]},{"c":4,"cells":["Regimul politic","cum se exercită puterea și ce o limitează","stat de drept, democratic"],"hl":true}],"note":{"c":5,"t":"Monarhie democratică: Regatul Unit. Republică autoritară: posibilă. Forma ≠ regimul."}},{"id":"2.2","type":"concept","k":"02 · Grecia clasică","t":"Nașterea *comparației*","img":"m2_liceu","mark":{"x":4,"y":12,"w":44,"h":22,"l":"citim constituțiile"},"n":["Grecii sunt primii care compară sistematic modurile de organizare a puterii. Lumea lor oferea sute de cetăți autonome, cu constituții diferite.","Herodot, în secolul al cincilea înainte de Hristos, consemnează prima dezbatere comparativă. Criteriul ei este numărul celor care conduc: unul, câțiva sau cei mulți.","Platon scrie Republica în secolul al patrulea, după înfrângerea Atenei în războiul peloponesiac, în 404, după regimul oligarhic al celor Treizeci și după condamnarea la moarte a lui Socrate de către democrația restaurată, în 399.","Instabilitatea regimurilor îi orientează întrebarea: de ce cad regimurile?","Aristotel organizează, la Liceu, culegerea constituțiilor multor cetăți. S-a păstrat Constituția atenienilor. În Politica, el propune o clasificare după două criterii."],"notes":[{"c":1,"n":"01","h":"Herodot","p":"criteriul numărului: unul, câțiva, cei mulți","r":"Istorii III.80–82"},{"c":2,"n":"02","h":"Platon, Republica","p":"după 404 î.Hr., cei Treizeci și moartea lui Socrate (399 î.Hr.)"},{"c":3,"n":"","h":"„De ce cad regimurile?”","p":""},{"c":4,"n":"03","h":"Aristotel, Liceul","p":"constituții culese; Politica III–IV: două criterii"}]},{"id":"2.3","type":"timeline","k":"03 · Modernitatea","t":"Puterea trebuie să oprească *puterea*","img":"m2_cantar","n":["În epoca modernă, întrebarea se mută. Nu mai contează doar câți conduc, ci de unde vine dreptul de a conduce și unde se oprește puterea.","Conflictele religioase din secolele șaisprezece și șaptesprezece duc la separarea puterii politice de cea religioasă. John Locke, Scrisoare despre toleranță, 1689.","Montesquieu, în Despre spiritul legilor, 1748, formulează principiul că puterea trebuie să oprească puterea și descrie separarea puterilor pe modelul constituției engleze.","Tocqueville, în 1835, semnalează un pericol propriu democrațiilor: tirania majorității."],"items":[{"c":1,"y":"1689","h":"Locke, Scrisoare despre toleranță","p":"puterea politică separată de cea religioasă"},{"c":2,"y":"1748","h":"Montesquieu, Despre spiritul legilor","p":"„puterea să oprească puterea” (XI.4); separarea puterilor (XI.6)"},{"c":3,"y":"1835","h":"Tocqueville, Despre democrația în America","p":"tirania majorității"}]},{"id":"2.4","type":"concept","k":"04 · Secolul XX","t":"Puterea care vrea și *gândirea*","img":"m2_total","mark":{"x":22,"y":32,"w":56,"h":20,"l":"citim controlul"},"n":["În secolul douăzeci, regimurile național-socialist și stalinist produc o formă de putere fără precedent.","Nu e vorba doar de absența limitelor, ci de pretenția de a controla întreaga viață, inclusiv gândirea.","Karl Popper, în Societatea deschisă și dușmanii ei, în 1945, și Hannah Arendt, în Originile totalitarismului, în 1951, analizează originile intelectuale și mecanismele acestei forme.","Distopiile literare, ale lui Zamiatin, Huxley și Orwell, o anticipează și o fac vizibilă prin ficțiune."],"lead":{"c":1,"t":"nu doar fără limite: *controlul întregii vieți*, inclusiv al gândirii"},"notes":[{"c":2,"n":"01","h":"Popper, 1945","p":"Societatea deschisă și dușmanii ei"},{"c":2,"n":"02","h":"Arendt, 1951","p":"Originile totalitarismului"},{"c":3,"n":"03","h":"Distopiile literare","p":"Zamiatin · Huxley · Orwell"}]},{"id":"2.5","type":"map","k":"05 · Harta modulului","t":"Trei întrebări, trei *surse*, două limite","n":["Ca să nu te pierzi, iată harta modulului.","Teoriile clasice răspund la trei întrebări diferite: cine conduce, la Herodot; de ce cad regimurile, la Platon; în folosul cui se exercită puterea, la Aristotel.","Regimurile reale se deosebesc apoi prin sursa dreptului de a conduce: moștenirea, consimțământul sau voința divină.","La limitele scalei se află absența puterii, anarhia; idealul imaginat, utopia; și puterea totală, distopia și totalitarismul."],"rows3":[{"c":1,"h":"Trei întrebări","items":["Cine conduce? · Herodot","De ce cad regimurile? · Platon","În folosul cui? · Aristotel"]},{"c":2,"h":"Trei surse ale dreptului de a conduce","items":["moștenirea · monarhia","consimțământul · democrația","voința divină · teocrația"]},{"c":3,"h":"La limite","items":["absența puterii · anarhia","idealul imaginat · utopia","puterea totală · distopia, totalitarismul"]}]},{"id":"2.6","type":"triptych","k":"06 · Herodot, Istorii III.80–82","t":"Trei perși *dezbat* constituția","n":["După moartea regelui, trei nobili perși discută ce regim să instituie. Dezbaterea este, foarte probabil, o construcție literară grecească pusă în gura unor perși.","Otanes apără puterea celor mulți: egalitate în fața legii, isonomia, magistrați trași la sorți și obligați să dea socoteală. Argumentul lui: puterea necontrolată a unuia singur produce trufie și abuz.","Megabyzos apără puterea celor puțini. Mulțimea este needucată și impulsivă; puterea trebuie dată celor mai buni. Competența contează mai mult decât numărul.","Dareios apără puterea unuia. Oligarhia produce rivalități, democrația produce corupție, și amândouă sfârșesc în monarhie. Atunci e mai bine să începi direct cu cel mai bun om.","Contribuția dezbaterii este criteriul numărului. Limita ei: criteriul nu spune nimic despre calitatea guvernării. Fiecare poziție presupune, fără să demonstreze, că formele rivale degenerează."],"cols":[{"c":1,"w":"cei mulți","h":"Otanes","img":"m2_persia_multi","pos":"50% 50%","p":"isonomia, tragere la sorți, magistrați care dau socoteală. Puterea unuia produce trufie și abuz."},{"c":2,"w":"cei puțini","h":"Megabyzos","img":"m2_persia","pos":"50% 50%","p":"Mulțimea e needucată și impulsivă. Competența contează mai mult decât numărul."},{"c":3,"w":"unul","h":"Dareios","img":"m2_persia_rege","pos":"50% 40%","p":"Oligarhia aduce rivalități, democrația corupție. Mai bine direct cel mai bun om."}],"foot":{"c":4,"t":"Contribuția: criteriul *numărului*. Limita: nu spune nimic despre calitatea guvernării."}},{"id":"2.7","type":"diagram","d":"stairs","k":"07 · Platon, Republica VIII–IX","t":"Cum *cad* regimurile","n":["Platon construiește o analogie între structura sufletului și structura cetății. Fiecărui regim îi corespunde un tip de om și un principiu dominant.","Teza: regimurile se succed printr-o degenerare internă. Fiecare cade prin excesul propriului principiu.","Aristocrația, în care conduc filosofii după principiul înțelepciunii, se corupe prin urmași nepotriviți și prin conflictul dintre cei care prețuiesc virtutea și cei care prețuiesc bogăția.","Timocrația, a războinicilor, cu principiul onoarei, se corupe prin acumularea ascunsă de avere.","Oligarhia, a bogaților, rupe cetatea în bogați și săraci, iar săracii preiau puterea.","Democrația, în care conduc toți, cu principiul libertății, nu mai respectă nicio autoritate. Poporul își alege un protector, căruia îi dă tot mai multă putere.","Tirania: conduce unul, după dorința fără frâu. Protectorul își elimină adversarii și pornește războaie ca să rămână necesar. Libertatea excesivă se transformă în sclavie excesivă."],"steps":[{"c":2,"h":"Aristocrația","w":"conduc filosofii","p":"înțelepciunea","x":"urmași nepotriviți; virtute contra bogăție","r":"546a–547c"},{"c":3,"h":"Timocrația","w":"conduc războinicii","p":"onoarea","x":"averea acumulată în ascuns","r":"547c–551b"},{"c":4,"h":"Oligarhia","w":"conduc bogații","p":"bogăția","x":"cetatea ruptă în bogați și săraci","r":"551b–557a"},{"c":5,"h":"Democrația","w":"conduc toți","p":"libertatea","x":"nicio autoritate; un „protector”","r":"557a–565d"},{"c":6,"h":"Tirania","w":"conduce unul","p":"dorința fără frâu","x":"libertatea excesivă → sclavie excesivă","r":"565d–569c; 564a"}]},{"id":"2.8","type":"procon","k":"08 · Corabia statului","t":"Cine ține *cârma*?","video":"v_corabia","img":"m2_corabia_gr","n":["De ce contează teza lui Platon? Ea explică instabilitatea regimurilor prin cauze interne, nu prin accident. Și oferă primul argument că orice regim are nevoie de frâne.","Argumentul corăbiei formulează o obiecție durabilă la adresa democrației. Corabia statului ar fi condusă de cel care convinge echipajul, nu de cel care știe să navigheze.","Obiecțiile: succesiunea este schematică, nu istorică. Aristotel o critică deja, în Politica, cartea a cincea.","Regimul ideal presupune o elită competentă și incoruptibilă, fără să spună cine o controlează.","Iar Karl Popper vede în proiectul lui Platon prima justificare intelectuală a societății închise."],"pro":[{"c":0,"h":"Cauze interne","p":"Instabilitatea nu e accident; orice regim are nevoie de frâne."},{"c":1,"h":"Argumentul corăbiei","p":"Cârma la cel care convinge echipajul, nu la cel care știe să navigheze.","r":"488a–489a"}],"con":[{"c":2,"h":"Schematic, nu istoric","p":"Aristotel critică deja succesiunea.","r":"Politica V.12"},{"c":3,"h":"Cine controlează elita?","p":"Elita competentă și incoruptibilă e doar presupusă."},{"c":4,"h":"Societatea închisă","p":"Prima ei justificare intelectuală.","r":"Popper, 1945"}]},{"id":"2.9","type":"ex","ex":"sequence","k":"Exercițiu · Ordonează","t":"Scara *degenerării*","n":["Refă scara lui Platon. Pune cele cinci regimuri în ordinea în care se degradează unul în altul, de la primul la ultimul.","Folosește săgețile sau tastele, apoi apasă Verifică."],"items":[{"t":"Aristocrația","p":"înțelepciunea"},{"t":"Timocrația","p":"onoarea"},{"t":"Oligarhia","p":"bogăția"},{"t":"Democrația","p":"libertatea"},{"t":"Tirania","p":"dorința fără frâu"}],"shuffle":[3,0,4,2,1],"f":"Fiecare regim cade prin excesul propriului principiu: înțelepciune → onoare → bogăție → libertate → dorință fără frâu."},{"id":"2.10","type":"ex","ex":"grid","k":"Exercițiu · Clasifică","t":"Aristotel: două criterii, *șase* regimuri","n":["Aristotel lucrează comparativ, pe baza constituțiilor adunate la Liceu.","Regimurile se clasifică după două criterii: câți conduc și în folosul cui.","Regimurile care urmăresc folosul comun sunt drepte. Cele care urmăresc folosul celor care guvernează sunt deviații.","Așază cele șase regimuri în tabel. Selectează un regim, apoi căsuța potrivită."],"rowsH":["Unul","Câțiva","Cei mulți"],"colsH":["Forma dreaptă · binele comun","Forma deviată · interesul celor care conduc"],"tokens":[{"t":"regalitate","r":0,"col":0},{"t":"tiranie","r":0,"col":1},{"t":"aristocrație","r":1,"col":0},{"t":"oligarhie","r":1,"col":1},{"t":"politeia","r":2,"col":0},{"t":"democrație","r":2,"col":1}],"ref":"Politica III.6–7, 1278b–1279b; 1279a17–21","f":"Atenție la ultimul rând: la Aristotel, „democrația” este forma deviată, iar forma dreaptă a puterii celor mulți se numește politeia."},{"id":"2.11","type":"procon","k":"09 · Aristotel, cântărit","t":"Un regim se judecă după *scopul* puterii","n":["O precizare de vocabular. La Aristotel, democrația desemnează forma deviată: cei mulți, adică săracii, conduc în interesul lor. Semnul deviației este guvernarea prin decrete votate de la caz la caz, deasupra legii.","Democrația constituțională modernă se apropie mai mult de ceea ce Aristotel numea politeia.","Argumentele pentru: al doilea criteriu este decisiv și are caracter normativ. Un regim se judecă după scopul puterii, nu după numărul guvernanților.","Aristotel observă că diferența reală dintre oligarhie și democrație este bogăția și sărăcia, nu numărul.","Politeia, un regim mixt sprijinit pe o clasă de mijloc numeroasă, este cea mai stabilă dintre formele realizabile. Și mulți oameni obișnuiți, judecând împreună, pot judeca mai bine decât câțiva excelenți.","Obiecțiile: criteriul binelui comun lasă deschisă întrebarea cine îl definește.","Iar clasificarea presupune cetatea mică și o cetățenie restrânsă, din care sclavii și femeile sunt excluși."],"thesis":[{"c":0,"t":"„democrația” lui Aristotel = forma deviată: decrete votate de la caz la caz, deasupra legii (IV.4)"},{"c":1,"t":"democrația constituțională modernă ≈ politeia"}],"pro":[{"c":2,"h":"Scopul puterii","p":"Criteriul normativ: binele comun sau interesul guvernanților."},{"c":3,"h":"Bogăție și sărăcie","p":"Diferența reală dintre oligarhie și democrație.","r":"III.8"},{"c":4,"h":"Politeia și judecata multora","p":"Clasa de mijloc dă stabilitate; mulți judecă împreună mai bine.","r":"IV.11; III.11"}],"con":[{"c":5,"h":"Cine definește binele comun?","p":"Întrebarea rămâne deschisă."},{"c":6,"h":"Cetatea mică","p":"Cetățenie restrânsă: sclavii și femeile excluși."}]},{"id":"2.12","type":"procon","k":"10 · Monarhia","t":"Puterea *unuia*","img":"m2_coroana","n":["Monarhia: puterea supremă aparține unei singure persoane, de regulă pe viață și prin moștenire.","Monarhia absolută nu este limitată de lege și se justifică prin dreptul divin sau prin tradiție. În monarhia constituțională, puterea reală aparține parlamentului și guvernului.","Pentru: unitatea deciziei evită blocajele și facțiunile. Monarhul ereditar nu gândește în termenii unui mandat scurt.","Hobbes argumentează că în monarhie interesul privat coincide cu cel public, pentru că bogăția și puterea monarhului depind de prosperitatea supușilor.","Contra: calitatea guvernării depinde de o singură persoană, desemnată prin naștere, nu prin merit. Nu există un mijloc legal de a înlocui un monarh rău.","Și, spune Aristotel, puterea unuia devine tiranie atunci când servește interesul propriu."],"thesis":[{"c":0,"t":"un singur om, de regulă pe viață și prin moștenire"},{"c":1,"t":"absolută (drept divin, tradiție) · constituțională (puterea la parlament și guvern)"}],"pro":[{"c":2,"h":"Unitatea deciziei","p":"Fără blocaje și facțiuni; perspectivă dincolo de un mandat scurt."},{"c":3,"h":"Interes privat = interes public","p":"Bogăția monarhului depinde de prosperitatea supușilor.","r":"Hobbes, Leviathan, cap. XIX"}],"con":[{"c":4,"h":"Prin naștere, nu prin merit","p":"Niciun mijloc legal de a înlocui un monarh rău."},{"c":5,"h":"Alunecarea în tiranie","p":"Când puterea unuia servește interesul propriu.","r":"Aristotel"}]},{"id":"2.13","type":"table","k":"11 · Democrația","t":"Atena și democrația *constituțională*","img":"m2_urna","n":["Democrația ateniană din secolele cinci și patru înainte de Hristos și democrația constituțională modernă diferă structural.","La Atena decideau cetățenii, direct, în adunare. Astăzi decid reprezentanți aleși.","Magistrații erau majoritar trași la sorți. Astăzi sunt aleși prin vot.","Cetățeni erau bărbații atenieni liberi. Astăzi sunt toți adulții.","Iar limitele puterii majorității erau puține. Astăzi o limitează constituția, drepturile și instanțele."],"head":["","Atena, sec. V î.Hr.","Democrația constituțională"],"rows":[{"c":1,"cells":["Cine decide","cetățenii, direct, în adunare","reprezentanți aleși"]},{"c":2,"cells":["Magistrații","majoritar trași la sorți","aleși prin vot"]},{"c":3,"cells":["Cetățenii","bărbați atenieni liberi","toți adulții"]},{"c":4,"cells":["Limitele majorității","puține","constituție, drepturi, instanțe"]}]},{"id":"2.14","type":"procon","k":"12 · Democrația, cântărită","t":"Guvernanții răi, înlăturați *fără sânge*","n":["Ce spune pentru democrație? Judecata colectivă a multora poate fi superioară judecății câtorva excelenți, susține deja Aristotel.","Criteriul lui Karl Popper: important nu este cine conduce, ci ca guvernanții răi să poată fi înlăturați fără vărsare de sânge, prin alegeri.","Separarea puterilor, la Montesquieu, și drepturile garantate de constituție limitează puterea, inclusiv pe cea a majorității.","Ce spune împotrivă? Argumentul competenței, al lui Platon: corabia statului.","Și tirania majorității: majoritatea poate oprima o minoritate la fel de eficient ca un tiran, avertizează Tocqueville."],"pro":[{"c":0,"h":"Judecata multora","p":"Poate fi superioară celei a câtorva excelenți.","r":"Aristotel, III.11"},{"c":1,"h":"Criteriul lui Popper","p":"Guvernanții răi pot fi înlăturați prin alegeri, fără vărsare de sânge.","r":"Societatea deschisă, vol. I, cap. 7"},{"c":2,"h":"Limitele puterii","p":"Separarea puterilor și drepturile constituționale.","r":"Montesquieu"}],"con":[{"c":3,"h":"Argumentul competenței","p":"Corabia statului.","r":"Platon"},{"c":4,"h":"Tirania majorității","p":"Majoritatea poate oprima o minoritate ca un tiran.","r":"Tocqueville, vol. I, partea a II-a, cap. 7"}]},{"id":"2.15","type":"procon","k":"13 · Teocrația","t":"Cine *interpretează* voința divină?","img":"m2_templu","n":["Termenul teocrație îi aparține lui Iosif Flavius. El descrie astfel constituția lui Moise: stăpânirea și puterea sunt atribuite lui Dumnezeu.","Criteriul nu mai este numărul celor care conduc, ci sursa dreptului de a conduce.","Se disting regalitatea sacră, în care conducătorul este considerat divin sau trimis de divinitate, și hierocrația, în care conduc cei care au autoritatea de a interpreta voința divină.","Pentru: legea nu depinde de voința schimbătoare a oamenilor, ci de o normă considerată superioară. Comunitatea are un temei moral comun și stabil.","Contra: problema interpretului. Cine interpretează voința divină devine, de fapt, conducătorul. Iar cine nu împărtășește credința nu are temei să accepte autoritatea.","Răspunsul modern este separarea puterii politice de cea religioasă, la Locke, în 1689."],"thesis":[{"c":0,"t":"stăpânirea și puterea atribuite lui Dumnezeu","r":"Iosif Flavius, Contra lui Apion II.165"},{"c":2,"t":"regalitate sacră · hierocrație"}],"pro":[{"c":3,"h":"O normă superioară","p":"Legea nu depinde de voința schimbătoare a oamenilor; un temei moral comun."}],"con":[{"c":4,"h":"Problema interpretului","p":"Interpretul devine conducătorul; necredincioșii n-au temei să accepte."},{"c":5,"h":"Răspunsul modern","p":"Separarea puterii politice de cea religioasă.","r":"Locke, 1689"}]},{"id":"2.16","type":"procon","k":"14 · Anarhia și anarhismul","t":"O stare și o *doctrină*","img":"m2_tron","n":["Atenție la două cuvinte apropiate. Anarhia este o stare: absența oricărei puteri comune. Pentru Hobbes, starea naturală.","Anarhismul este o doctrină: orice autoritate politică impusă este nelegitimă, iar oamenii pot coopera fără stat.","Proudhon, în 1840, este primul gânditor care se declară anarhist. Kropotkin, în Întrajutorarea, în 1902, susține că cooperarea este un factor al evoluției. Robert Paul Wolff, în 1970, argumentează că a asculta de stat doar pentru că este stat contrazice autonomia morală.","Pentru: orice putere tinde să abuzeze, iar singura garanție completă este absența ei. Oamenii cooperează spontan mai mult decât presupune Hobbes.","Contra: fără putere comună, rămâne neclar cine îl protejează pe cel slab de cel puternic. Cooperarea spontană este documentată în grupuri mici, nu la scara unei societăți.","Și, în absența statului, grupurile cele mai organizate își pot impune propria putere."],"thesis":[{"c":0,"t":"anarhia: o stare, absența puterii comune"},{"c":1,"t":"anarhismul: o doctrină, autoritatea impusă e nelegitimă"}],"pro":[{"c":2,"h":"Proudhon · Kropotkin · Wolff","p":"1840 · Întrajutorarea, 1902 · autonomia morală, 1970"},{"c":3,"h":"Garanția completă","p":"Orice putere tinde să abuzeze; oamenii cooperează mai mult decât crede Hobbes."}],"con":[{"c":4,"h":"Cine îl apără pe cel slab?","p":"Cooperarea spontană e documentată în grupuri mici."},{"c":5,"h":"Puterea celor organizați","p":"Fără stat, grupurile cele mai organizate se impun."}]},{"id":"2.17","type":"procon","k":"15 · Utopia","t":"Niciun loc, un loc *bun*","img":"m2_oi","n":["Thomas Morus publică Utopia în 1516. Termenul combină ou-topos, niciun loc, și eu-topos, loc bun. Precursorul este cetatea ideală din Republica lui Platon.","Pentru: utopia are o funcție critică. Morus descrie Anglia în care oile mănâncă oameni, adică țăranii alungați de pe pământ prin îngrădirea pășunilor.","Ea funcționează ca etalon: arată cât de departe este regimul real de cel posibil.","Contra: Popper distinge ingineria utopică de ingineria graduală. Cine vrea să construiască întreaga societate după un plan perfect trebuie să îi elimine pe cei care nu se potrivesc planului.","Alternativa sunt reformele parțiale, care pot fi corectate."],"thesis":[{"c":0,"t":"ou-topos (niciun loc) + eu-topos (loc bun) · Morus, 1516"}],"pro":[{"c":1,"h":"Funcția critică","p":"„Oile mănâncă oameni”: țăranii alungați prin îngrădirea pășunilor."},{"c":2,"h":"Etalonul","p":"Cât de departe e regimul real de cel posibil."}],"con":[{"c":3,"h":"Ingineria utopică","p":"Planul perfect îi elimină pe cei care nu se potrivesc.","r":"Popper, vol. I, cap. 9"},{"c":4,"h":"Alternativa","p":"Ingineria graduală: reforme parțiale, corectabile."}]},{"id":"2.18","type":"procon","k":"16 · Distopia și totalitarismul","t":"Utopia dusă până la *capăt*","video":"v_camere","img":"m2_camere","n":["Distopia este societatea imaginată în care puterea a devenit totală. Au existat termeni mai vechi: cacotopia, la Bentham, în 1818, și dys-topians, la Mill, în 1868.","Literatura propune trei modele. Control prin rațiune și transparență totală: Zamiatin, Noi, scris în 1920 și 1921. Control prin plăcere și condiționare: Huxley, Minunata lume nouă, 1932. Control prin frică, supraveghere și rescrierea trecutului: Orwell, 1984, publicat în 1949.","Hannah Arendt descrie totalitarismul ca dominare totală. Spre deosebire de tirania clasică, el vrea să controleze și gândirea, nu doar faptele.","Pentru: distopia face vizibil, prin ficțiune, pericolul descris de Platon, un principiu dus la exces se transformă în opusul lui. Teza de discutat: distopia nu este opusul utopiei, ci utopia dusă până la capăt, un plan al binelui impus fără limite.","Contra: conceptul de totalitarism este disputat în istoriografie. Asimilarea regimurilor nazist și sovietic într-o singură categorie a fost criticată pentru că reduce diferențe ideologice și sociale reale.","Iar ficțiunea ilustrează un pericol, dar nu dovedește o lege istorică."],"models":[{"c":1,"h":"Zamiatin, Noi","p":"rațiune și transparență totală","y":"1920–1921"},{"c":1,"h":"Huxley, Minunata lume nouă","p":"plăcere și condiționare","y":"1932"},{"c":1,"h":"Orwell, 1984","p":"frică, supraveghere, rescrierea trecutului","y":"1949"}],"pro":[{"c":2,"h":"Dominarea totală","p":"Controlul gândirii, nu doar al faptelor.","r":"Arendt, 1951"},{"c":3,"h":"Utopia dusă până la capăt","p":"Un plan al binelui impus fără limite."}],"con":[{"c":4,"h":"Un concept disputat","p":"Nazism și stalinism într-o categorie: diferențe reale reduse."},{"c":5,"h":"Ficțiune, nu lege istorică","p":"Ilustrează un pericol, nu îl dovedește."}]},{"id":"2.19","type":"ex","ex":"diagnose","k":"Exercițiu · Diagnostichează","t":"Ce regim are *cetatea*?","n":["Șase cetăți imaginare. Citește descrierea fiecăreia și alege regimul care i se potrivește.","Ține minte cele două criterii ale lui Aristotel și sursa dreptului de a conduce."],"items":[{"t":"În cetatea Alfa conduce un singur om, după legi, urmărind folosul tuturor.","o":["regalitate","tiranie","politeia","oligarhie"],"a":0,"f":"Unul singur, binele comun: forma dreaptă, regalitatea."},{"t":"În cetatea Beta, cei mai bogați fac legile ca să-și apere averile.","o":["aristocrație","oligarhie","democrație","timocrație"],"a":1,"f":"Câțiva, în interes propriu, iar criteriul real e bogăția: oligarhia (Aristotel, III.8)."},{"t":"În cetatea Gama, adunarea votează de la caz la caz decrete care trec peste lege, în folosul celor mulți și săraci.","o":["politeia","democrația în sensul lui Aristotel","regalitate","anarhie"],"a":1,"f":"Decretele deasupra legii sunt semnul deviației: „democrația” aristotelică (IV.4)."},{"t":"În cetatea Delta, legile sunt stabilite de cei care au autoritatea de a interpreta voința divină.","o":["regalitate sacră","hierocrație","monarhie constituțională","aristocrație"],"a":1,"f":"Conduc interpreții voinței divine: hierocrația, o formă de teocrație."},{"t":"În cetatea Epsilon nu există nicio putere comună. Fiecare se apără cum poate.","o":["anarhism","anarhie","utopie","democrație directă"],"a":1,"f":"Absența puterii comune este o stare: anarhia. Anarhismul ar fi doctrina care o consideră dezirabilă."},{"t":"În cetatea Zeta, guvernul vrea să controleze nu doar faptele, ci și gândurile cetățenilor.","o":["tiranie clasică","monarhie absolută","totalitarism","oligarhie"],"a":2,"f":"Pretenția de a controla și gândirea distinge totalitarismul de tirania clasică (Arendt)."}]},{"id":"2.20","type":"diagram","d":"axis","k":"Concluzie","t":"Între absența puterii și puterea *fără limite*","n":["Analiza regimurilor duce la trei rezultate.","Primul: un regim se judecă după scopul puterii, binele comun sau interesul celor care conduc.","Al doilea: orice regim poate degenera. Puterea fără frâne tinde spre tiranie și, la limită, spre dominare totală.","Al treilea: puterea trebuie limitată și trebuie să poată fi schimbată fără violență, cum arată Montesquieu și Popper.","Regimurile reale se așază între două extreme de evitat: absența puterii comune, anarhia, și puterea fără limite, tirania și totalitarismul.","Utopia nu este un punct pe această axă, ci un etalon imaginat deasupra ei."],"res":[{"c":1,"n":"01","t":"Un regim se judecă după *scopul* puterii.","r":"Aristotel"},{"c":2,"n":"02","t":"Orice regim poate degenera; fără frâne, spre tiranie și dominare totală.","r":"Platon, Arendt"},{"c":3,"n":"03","t":"Puterea trebuie limitată și schimbabilă fără violență.","r":"Montesquieu, Popper"}],"axisL":{"c":4,"h":"anarhia","p":"absența puterii comune"},"axisR":{"c":4,"h":"tirania · totalitarismul","p":"puterea fără limite"},"axisM":{"c":4,"h":"regimurile reale"},"utopia":{"c":5,"h":"utopia","p":"un etalon imaginat deasupra axei"}},{"id":"2.21","type":"stats","k":"Ce spun cercetările","t":"Tirania nu are nevoie de monștri, ci de oameni care *ascultă*","img":"m2_panou","n":["Trei cercetări empirice sprijină, cu limite precizate, aceste rezultate.","Nicio foamete majoră nu a avut loc într-o democrație funcțională cu presă liberă, arată Amartya Sen. Teza este discutată pe cazuri-limită și privește foametea, nu orice formă de sărăcie.","După douăzeci și cinci de ani, produsul intern brut pe locuitor al țărilor democratizate este cu aproximativ douăzeci la sută mai mare decât ar fi fost fără democratizare, arată Acemoglu și colaboratorii săi. Efectul este moderat, lent și sensibil la eșantionul de țări.","În experimentul lui Stanley Milgram, din 1963, douăzeci și șase din patruzeci de participanți, adică șaizeci și cinci la sută, au mers până la nivelul maxim de șoc la cererea unei autorități.","Etica și o parte din rezultate au fost contestate, de Gina Perry, în 2012. O replicare parțială, a lui Jerry Burger, în 2009, a obținut rezultate apropiate.","Concluzia: tirania nu are nevoie de monștri, ci de oameni care ascultă."],"stats":[{"c":1,"v":"0","p":"foamete majore într-o democrație funcțională cu presă liberă","r":"Sen, 1981; 1999","lim":"privește foametea, nu orice sărăcie"},{"c":2,"v":"≈ +20%","p":"PIB pe locuitor după 25 de ani de democratizare","r":"Acemoglu et al., 2019","lim":"efect moderat, lent, sensibil la eșantion"},{"c":3,"v":"26 / 40","p":"participanți (65%) până la șocul maxim, la cererea unei autorități","r":"Milgram, 1963","lim":"contestat (Perry, 2012); replicare parțială (Burger, 2009)","bar":65}],"foot":{"c":5,"t":"Tirania nu are nevoie de monștri, ci de oameni care *ascultă*."}},{"id":"2.22","type":"conclusion","k":"Teza modulului","t":"Binele comun și puterea *limitată*","n":["Teza finală a modulului: un regim bun servește binele comun și are puterea limitată.","Rămâne deschisă o întrebare pe care criteriul lui Aristotel o presupune fără să o rezolve.","Cine stabilește ce este binele comun: comunitatea sau fiecare individ? De la această întrebare pornește modulul trei."],"big":{"c":0,"t":"Un regim bun servește binele comun și are puterea *limitată*."},"work":{"c":1,"t":"Criteriul aristotelic presupune un răspuns pe care nu îl dă."},"next":{"c":2,"t":"Cine stabilește ce este binele comun: comunitatea sau fiecare individ?","m":"Modulul 03"}},{"id":"2.23","type":"quiz","k":"Verificare","t":"Cinci întrebări, cu *explicații*","n":["Verifică-te. Cinci întrebări, cu explicații după fiecare răspuns."],"qs":[{"q":"Regatul Unit este o monarhie. Ce putem spune despre regimul său politic?","o":["E sigur autoritar, pentru că e monarhie.","Monarhia e formă de guvernământ; regimul poate fi democratic.","Nu are regim politic, doar formă de guvernământ.","E o teocrație, pentru că monarhul are rol religios."],"a":1,"f":"Forma de guvernământ (monarhie sau republică) nu decide regimul: o monarhie poate fi democratică."},{"q":"După Platon, de ce cade fiecare regim?","o":["Prin invazii externe.","Prin excesul propriului principiu.","Prin voința zeilor.","Pentru că legile sunt prea vechi."],"a":1,"f":"Degenerarea e internă: libertatea excesivă, de exemplu, se transformă în sclavie excesivă."},{"q":"Care e criteriul decisiv, normativ, al lui Aristotel?","o":["Câți conduc.","În folosul cui se exercită puterea.","Cât de bogată este cetatea.","Cât de veche este constituția."],"a":1,"f":"Numărul descrie; scopul puterii (binele comun sau interesul guvernanților) judecă."},{"q":"Ce susține criteriul lui Popper despre democrație?","o":["Să conducă cei mai înțelepți.","Guvernanții răi să poată fi înlăturați fără vărsare de sânge.","Majoritatea are întotdeauna dreptate.","Statul să fie desființat."],"a":1,"f":"Nu contează cine conduce, ci posibilitatea de a-i schimba pe guvernanți prin alegeri."},{"q":"Ce arată experimentul lui Milgram (1963), cu limitele lui?","o":["Că doar oamenii răi fac rău.","Că 26 din 40 de participanți au ascultat de o autoritate până la șocul maxim.","Că nimeni nu ascultă de autorități.","Că democrațiile nu au foamete."],"a":1,"f":"65% au mers până la capăt. Etica și o parte din rezultate sunt contestate, dar o replicare parțială a dat rezultate apropiate."}]},{"id":"2.24","type":"ws","ws":"m2","k":"Fișă de lucru · Aplică","t":"Fișa ta de *lucru*","n":["Urmează fișa de lucru a modulului doi.","Trei etape, ca modulul: istoria ideii de regim, regimurile reale și limitele lor. Apoi feedback-ul.","Indiciul de lângă fiecare întrebare te duce la ecranul unde găsești răspunsul.","Răspunsurile se salvează singure. La final, descarcă fișa și trimite-o profesorului tău."]},{"id":"2.25","type":"biblio","k":"Resurse","t":"Bibliografia *modulului*","n":["Bibliografia modulului doi: surse primare, lucrări didactice, exegeză și studii."],"bib":"m2"}]},{"id":"m3","num":"03","title":"Cine stabilește *binele comun*","sub":"Ideologiile politice","q":"Cine stabilește ce este binele comun: comunitatea sau fiecare individ?","thesis":"O ideologie este un răspuns la o problemă reală și devine periculoasă atunci când pretinde că este singurul răspuns.","cover":"m3_cover","screens":[{"id":"3.0","type":"cover","img":"m3_cover","mark":{"x":40,"y":22,"w":20,"h":26,"l":"citim ideile"},"n":["Modulul trei. Cine stabilește binele comun.","Modulul doi s-a încheiat cu o întrebare: cine stabilește ce este binele comun, comunitatea sau fiecare individ? Ideologiile politice sunt răspunsuri concurente la această întrebare.","Teza la care ajungem: o ideologie este un răspuns la o problemă reală și devine periculoasă atunci când pretinde că este singurul răspuns.","Un lucru trebuie spus de la început: acest modul face filosofie despre ideologii, nu propagandă pentru vreuna dintre ele."],"goals":[{"c":2,"t":"Explici cele trei funcții ale unei ideologii și o deosebești de filosofia politică și de programul politic."},{"c":2,"t":"Legi fiecare ideologie majoră de problema istorică la care a răspuns."},{"c":2,"t":"Compari cinci ideologii după cine stabilește binele comun."},{"c":2,"t":"Recunoști cele patru semne ale gândirii ideologice."}]},{"id":"3.1","type":"functions","k":"01 · Delimitarea noțiunii","t":"Descrie, evaluează, *prescrie*","n":["O ideologie este un sistem de idei despre cum ar trebui organizată societatea.","Ea îndeplinește trei funcții. Le vedem pe o singură temă, munca.","Descrie ce este greșit în societatea existentă: muncitorii sunt exploatați.","Evaluează cum ar trebui să fie societatea: munca trebuie plătită drept.","Prescrie ce trebuie făcut: muncitorii să se organizeze.","A treia funcție, cea practică, deosebește ideologia de o teorie care doar descrie."],"lead":{"c":0,"t":"Un sistem de idei despre cum ar trebui organizată societatea."},"fx":[{"c":2,"n":"01","h":"Descrie","p":"ce este greșit","e":"„Muncitorii sunt exploatați.”"},{"c":3,"n":"02","h":"Evaluează","p":"cum ar trebui să fie","e":"„Munca trebuie plătită drept.”"},{"c":4,"n":"03","h":"Prescrie","p":"ce trebuie făcut","e":"„Muncitorii să se organizeze.”"}],"foot":{"c":5,"t":"Funcția *practică* deosebește ideologia de o teorie descriptivă."}},{"id":"3.2","type":"table","k":"02 · Trei noțiuni distincte","t":"Înțelegere, acțiune, *guvernare*","n":["Trei noțiuni trebuie păstrate distincte.","Filosofia politică examinează întrebări și argumente și rămâne deschisă la obiecții. Scopul ei este înțelegerea.","Ideologia leagă idei într-un sistem coerent și mobilizează oameni în jurul lui. Scopul ei este acțiunea.","Programul politic traduce o ideologie în măsuri concrete, pentru alegeri. Scopul lui este guvernarea.","Acest curs rămâne la primul nivel: face filosofie despre ideologii."],"head":["","Ce face","Scopul"],"rows":[{"c":1,"cells":["Filosofia politică","examinează întrebări și argumente; rămâne deschisă la obiecții","înțelegerea"],"hl":true},{"c":2,"cells":["Ideologia","leagă idei într-un sistem coerent și mobilizează oameni în jurul lui","acțiunea"]},{"c":3,"cells":["Programul politic","traduce o ideologie în măsuri concrete, pentru alegeri","guvernarea"]}],"note":{"c":4,"t":"Cursul face filosofie despre ideologii, nu propagandă pentru vreuna dintre ele."}},{"id":"3.3","type":"timeline","k":"03 · Istoria cuvântului","t":"De la știința ideilor la *conștiința falsă*","img":"m3_carte","n":["Cuvântul are o istorie surprinzătoare.","Termenul idéologie este creat de Destutt de Tracy în 1796, cu sensul de știință a ideilor.","După 1800, Napoleon îi numește în batjocură ideologi pe adversarii săi. Termenul capătă un sens peiorativ: gândire abstractă, ruptă de realitate.","La Marx și Engels, în Ideologia germană, scrisă în 1845 și 1846, ideologia devine iluzie: idei care ascund interese.","Engels, într-o scrisoare din 1893, o descrie drept un proces îndeplinit conștient de gânditor, dar cu o conștiință falsă, ale cărei forțe motrice reale îi rămân necunoscute."],"items":[{"c":1,"y":"1796","h":"Destutt de Tracy","p":"idéologie: „știința ideilor”"},{"c":2,"y":"după 1800","h":"Napoleon","p":"„ideologi”: gândire abstractă, ruptă de realitate"},{"c":3,"y":"1845–1846","h":"Marx și Engels, Ideologia germană","p":"iluzie: idei care ascund interese"},{"c":4,"y":"1893","h":"Engels, scrisoarea către F. Mehring","p":"„conștiință falsă”"}]},{"id":"3.4","type":"table","k":"04 · Răspunsuri la crize","t":"Fiecare ideologie răspunde unei *probleme reale*","img":"m3_presa","n":["Fiecare ideologie majoră s-a format ca răspuns la o problemă istorică reală.","Liberalismul răspunde absolutismului, privilegiilor de naștere și comerțului controlat de stat și de bresle. Textele de referință: Locke, 1689, și Adam Smith, 1776.","Conservatorismul răspunde Revoluției Franceze: o societate demolată și reconstruită după un plan rațional, urmată de teroare. Textul de referință: Burke, 1790.","Socialismul răspunde revoluției industriale: zile de muncă de douăsprezece, paisprezece ore, munca copiilor, revoltele muncitorești, de la cartism la revoluțiile din 1848. Textul de referință: Marx și Engels, 1848.","Liberalismul social răspunde unei situații noi: votul se extinde, dar sărăcia și crizele economice lasă mulți fără șanse reale. Green, 1881; Beveridge, 1942; Rawls, 1971.","Libertarianismul răspunde economiilor planificate ale secolului douăzeci, în care statul decide producția, prețurile și viața economică. Hayek, 1944; Nozick, 1974."],"head":["Ideologia","Problema istorică","Texte de referință"],"rows":[{"c":1,"cells":["Liberalismul","absolutism, privilegii de naștere, comerț controlat de stat și bresle","Locke, 1689; Smith, 1776"]},{"c":2,"cells":["Conservatorismul","Revoluția Franceză: societate demolată și refăcută după un plan rațional, urmată de teroare","Burke, 1790"]},{"c":3,"cells":["Socialismul","revoluția industrială: 12–14 ore de muncă, munca copiilor, cartismul (1838–1848), 1848","Marx și Engels, 1848"]},{"c":4,"cells":["Liberalismul social","votul se extinde, dar sărăcia și crizele lasă mulți fără șanse reale","Green, 1881; Beveridge, 1942; Rawls, 1971"]},{"c":5,"cells":["Libertarianismul","economiile planificate: statul decide producția, prețurile, viața economică","Hayek, 1944; Nozick, 1974"]}]},{"id":"3.5","type":"timeline","k":"05 · Cine face parte din cetate?","t":"Votul se *lărgește*","img":"m3_vot","n":["Extinderea dreptului de vot arată că întrebarea cine face parte din cetate primește mereu un răspuns ideologic.","În Marea Britanie, votul se extinde la clasa de mijloc în 1832.","Noua Zeelandă este primul stat cu vot universal, inclusiv pentru femei, în 1893.","În România, votul universal pentru bărbați este introdus prin decret-lege în 1918. Votul universal fără deosebire de sex vine abia în 1946.","Fiecare lărgire a fost cerută de o mișcare: liberalii, cartismul, sufragetele."],"items":[{"c":1,"y":"1832","h":"Marea Britanie","p":"votul se extinde la clasa de mijloc"},{"c":2,"y":"1893","h":"Noua Zeelandă","p":"primul vot universal, inclusiv pentru femei"},{"c":3,"y":"1918","h":"România","p":"vot universal pentru bărbați, prin decret-lege"},{"c":3,"y":"1946","h":"România","p":"vot universal fără deosebire de sex"}],"note":{"c":4,"t":"Fiecare lărgire a fost cerută de o mișcare: liberalii, cartismul, sufragetele."}},{"id":"3.6","type":"diagram","d":"compass","k":"06 · Un model de clasificare","t":"Busola *ideologiilor*","n":["Ca să compari ideologiile, poți folosi un model didactic: busola ideologiilor. Are două axe.","Axa orizontală măsoară cât este lăsat pieței și cât redistribuie statul.","Axa verticală măsoară cine fixează valorile sociale: comunitatea sau individul.","Modelul simplifică și nu este o hartă definitivă. Anarhismul, de exemplu, nu încape bine în el. Îl vei folosi într-un exercițiu, după ce cunoști cele cinci ideologii."],"axX":{"c":1,"a":"statul redistribuie","b":"piața decide"},"axY":{"c":2,"a":"comunitatea fixează valorile","b":"individul fixează valorile"},"warn":{"c":3,"t":"Un model didactic, nu o hartă definitivă. Anarhismul nu încape bine în el."}},{"id":"3.7","type":"procon","k":"07 · Liberalismul","t":"Fiecare stabilește pentru sine *viața bună*","img":"m3_liberal","n":["Prima ideologie: liberalismul. Locke, Al doilea tratat despre guvernare, 1689. Adam Smith, Avuția națiunilor, 1776. Un răspuns la absolutismul monarhic și la economia reglementată de stat și de bresle.","Tezele: individul are drepturi naturale, viața, libertatea și proprietatea, anterioare statului. Puterea politică provine din consimțământul celor guvernați și este limitată de scopul protejării acestor drepturi.","Piața liberă produce prosperitate. Iar fiecare individ stabilește pentru sine ce este viața bună.","Pentru: libertatea și drepturile sunt protejate împotriva oricărei puteri, inclusiv a majorității. Pluralismul concepțiilor despre bine este respectat. Proprietatea întemeiată pe muncă justifică deținerea independent de rang.","Contra: libertatea formală nu folosește mult celui care nu are mijloacele să o exercite. Obiecția vine atât din socialism, cât și din liberalismul social.","Iar individul abstract, fără legături constitutive, este criticat de comunitarism."],"thesis":[{"c":1,"t":"drepturi naturale anterioare statului · putere din consimțământ, limitată"},{"c":2,"t":"piața liberă · fiecare stabilește pentru sine viața bună"}],"pro":[{"c":3,"h":"Drepturi contra oricărei puteri","p":"Inclusiv contra majorității; pluralism; proprietatea din muncă, nu din rang."}],"con":[{"c":4,"h":"Libertatea formală","p":"Puțin folositoare fără mijloacele de a o exercita."},{"c":5,"h":"Individul abstract","p":"Fără legături constitutive (critica comunitaristă)."}]},{"id":"3.8","type":"procon","k":"08 · Conservatorismul","t":"Un parteneriat între vii, morți și *nenăscuți*","img":"m3_radacini","n":["A doua: conservatorismul. Edmund Burke, Reflecții asupra Revoluției din Franța, 1790. Scrise înainte de Teroare și citite ulterior ca o anticipare a ei.","Tezele: instituțiile moștenite, familia, Biserica, proprietatea, constituția istorică, conțin experiența acumulată a generațiilor. Drepturile concrete, moștenite, sunt preferabile drepturilor abstracte ale omului.","Societatea este un parteneriat între cei vii, cei morți și cei care se vor naște. Binele comun este stabilit de comunitatea istorică.","Pentru: argumentul epistemic. Nicio generație și niciun plan rațional nu pot cunoaște toate funcțiile pe care le îndeplinesc instituțiile existente. Demolarea lor produce consecințe imprevizibile.","Burke nu respinge schimbarea, ci revoluția: un stat fără mijloacele vreunei schimbări este fără mijloacele conservării sale.","Contra: prudența poate deveni apărarea unor nedreptăți vechi, privilegii și excluderi. Și rămâne nedeterminat care tradiție trebuie conservată atunci când tradițiile sunt multiple sau în conflict."],"thesis":[{"c":1,"t":"instituțiile moștenite păstrează experiența generațiilor"},{"c":2,"t":"binele comun: stabilit de comunitatea istorică"}],"pro":[{"c":3,"h":"Argumentul epistemic","p":"Nimeni nu cunoaște toate funcțiile instituțiilor; demolarea are efecte imprevizibile."},{"c":4,"h":"Schimbare, nu revoluție","p":"Fără mijloacele schimbării, statul n-are mijloacele conservării."}],"con":[{"c":5,"h":"Nedreptăți vechi","p":"Prudența poate apăra privilegii; ce tradiție, când sunt mai multe?"}]},{"id":"3.9","type":"procon","k":"09 · Socialismul","t":"Egalitatea economică, condiție a *libertății* reale","img":"m3_fabrica","n":["A treia: socialismul. Marx și Engels, Manifestul Partidului Comunist, 1848. Marx, Capitalul, primul volum, 1867. Mai devreme, Proudhon formulase, în 1840, teza că proprietatea este furt.","Tezele: proprietatea asupra mijloacelor de producție dă unei clase putere asupra alteia. Egalitatea economică este condiția libertății reale.","Resursele trebuie controlate colectiv. Binele comun este stabilit de colectivitate.","Pentru: teoria arată că relațiile economice sunt relații de putere și că dependența economică poate anula libertățile juridice. Ea explică de ce egalitatea în fața legii coexistă cu mari inegalități de șanse.","Contra: controlul colectiv concentrează puterea în mâinile statului, cu riscul descris de distopie, avertizează Hayek. Planificarea centrală nu dispune de informația dispersată pe care o adună prețurile de piață.","Iar regimurile care s-au revendicat de la marxism în secolul douăzeci au fost totalitare."],"thesis":[{"c":1,"t":"proprietatea mijloacelor de producție = putere de clasă"},{"c":2,"t":"control colectiv · binele comun: stabilit de colectivitate"}],"pro":[{"c":3,"h":"Economia e putere","p":"Dependența economică poate anula libertățile juridice."}],"con":[{"c":4,"h":"Puterea concentrată","p":"Riscul distopiei; planificarea n-are informația prețurilor.","r":"Hayek, 1944"},{"c":5,"h":"Secolul XX","p":"Regimurile care s-au revendicat de la marxism au fost totalitare."}]},{"id":"3.10","type":"procon","k":"10 · Liberalismul social","t":"Libertatea ca putere *reală* de a acționa","img":"m3_social","n":["A patra: liberalismul social. Thomas Hill Green, Legislația liberală și libertatea contractului, 1881. Raportul Beveridge, din 1942, fundamentul statului social britanic de după război. Și John Rawls, O teorie a dreptății, 1971.","Tezele: libertatea este o putere reală de a acționa, nu doar absența constrângerii. Ea are nevoie de condiții: educație, sănătate, protecție socială.","Statul corectează inegalitățile fără să desființeze piața. Inegalitățile sunt acceptabile doar dacă îi avantajează pe cei mai defavorizați: este principiul diferenței, la Rawls. Binele comun este stabilit de indivizi, sprijiniți de stat.","Pentru: doctrina răspunde obiecției libertății formale fără să renunțe la drepturile individuale și la piață. Talentele și familia în care te naști țin de noroc, nu de merit. O distribuire care le ignoră nu poate fi considerată echitabilă.","Contra: statul social are costuri mari și poate genera birocrație și dependență. Redistribuirea prin impozitare restrânge libertatea celor care plătesc. Robert Nozick o compară cu munca forțată."],"thesis":[{"c":1,"t":"libertatea reală are nevoie de condiții: educație, sănătate, protecție socială"},{"c":2,"t":"principiul diferenței · binele comun: indivizii, sprijiniți de stat"}],"pro":[{"c":3,"h":"Norocul nu e merit","p":"Talentele și familia țin de noroc; distribuirea trebuie să țină cont."}],"con":[{"c":4,"h":"Costuri și libertatea celor care plătesc","p":"Birocrație, dependență; impozitarea comparată cu munca forțată.","r":"Nozick"}]},{"id":"3.11","type":"procon","k":"11 · Libertarianismul","t":"Statul *minimal*","img":"m3_cheie","n":["A cincea: libertarianismul. Friedrich Hayek, Drumul către servitute, 1944. Robert Nozick, Anarhie, stat și utopie, 1974. În anii optzeci, privatizările au aplicat o parte din aceste idei.","Tezele: planificarea centrală duce la pierderea libertății. Statul trebuie redus la protecția persoanei și a proprietății: statul minimal.","O distribuire este dreaptă dacă bunurile au fost dobândite și transferate legitim, indiferent de tiparul final. Este teoria îndreptățirii. Binele comun este stabilit exclusiv de individ.","Pentru: argumentul Wilt Chamberlain, al lui Nozick. Pornind de la orice distribuire considerată dreaptă, schimburile libere produc inegalități. Menținerea unui tipar egalitar ar cere intervenția continuă în viața oamenilor. În plus, resursele administrate privat sunt folosite mai eficient.","Contra: piața nu produce singură bunuri publice, apărare, infrastructură, cercetare fundamentală, și poate adânci inegalitățile.","Teoria îndreptățirii presupune că achizițiile inițiale au fost drepte, ceea ce istoria contrazice adesea. Iar punctul de plecare, moștenirea și talentul, nu este meritat."],"thesis":[{"c":1,"t":"planificarea duce la pierderea libertății · statul minimal"},{"c":2,"t":"teoria îndreptățirii · binele comun: exclusiv individul"}],"pro":[{"c":3,"h":"Argumentul Wilt Chamberlain","p":"Schimburile libere strică orice tipar; tiparul cere intervenție continuă.","r":"Nozick, 1974"}],"con":[{"c":4,"h":"Bunurile publice","p":"Apărarea, infrastructura, cercetarea fundamentală."},{"c":5,"h":"Achiziții inițiale","p":"Istoria contrazice adesea dreptatea lor; punctul de plecare nu e meritat."}]},{"id":"3.12","type":"two","k":"12 · Același fapt, două interpretări","t":"Gardul: *drept* câștigat sau început al inegalității?","video":"v_gard","img":"m3_gard","n":["Același fapt poate primi interpretări opuse. Exemplul: îngrădirea pământului comun și transformarea lui în proprietate privată, în Anglia, între secolele șaisprezece și nouăsprezece.","Pentru Locke, munca scoate lucrurile din starea comună și fixează proprietatea asupra lor. Proprietatea este un drept câștigat.","Pentru Rousseau, primul care a îngrădit un teren și a spus acesta este al meu a întemeiat societatea civilă și, odată cu ea, inegalitatea.","Faptul este același. Interpretarea depinde de cadrul ideologic."],"fact":{"c":0,"t":"Îngrădirea pământului comun · Anglia, sec. XVI–XIX"},"a":{"c":1,"h":"Locke","p":"Munca scoate lucrurile din starea comună: proprietatea e un drept câștigat.","r":"Al doilea tratat, § 28"},"b":{"c":2,"h":"Rousseau","p":"„Acesta este al meu”: începutul societății civile și al inegalității.","r":"Discursul, 1755"},"foot":{"c":3,"t":"Faptul e același; *interpretarea* depinde de cadrul ideologic."}},{"id":"3.13","type":"ex","ex":"compass","k":"Exercițiu · Așază","t":"Pune ideologiile pe *busolă*","n":["Folosește busola. Selectează pe rând fiecare ideologie și așaz-o în cadranul care i se potrivește, după tezele ei.","Ține minte: pozițiile sunt aproximative, iar modelul simplifică."],"axX":{"a":"statul redistribuie","b":"piața decide"},"axY":{"a":"comunitatea fixează valorile","b":"individul fixează valorile"},"quads":["sus-stânga","sus-dreapta","jos-stânga","jos-dreapta"],"tokens":[{"t":"Liberalismul","ok":[3],"f":"Piața liberă și fiecare individ își stabilește viața bună: jos-dreapta."},{"t":"Conservatorismul","ok":[1,0],"f":"Sus: comunitatea istorică stabilește binele comun. Pe orizontală, fișa nu îl fixează; Burke apără proprietatea moștenită, deci mai degrabă spre dreapta."},{"t":"Socialismul","ok":[0],"f":"Control colectiv al resurselor și binele comun stabilit de colectivitate: sus-stânga."},{"t":"Liberalismul social","ok":[2],"f":"Statul corectează inegalitățile fără să desființeze piața; binele comun îl stabilesc indivizii, sprijiniți de stat: jos-stânga, aproape de centru."},{"t":"Libertarianismul","ok":[3],"f":"Statul minimal și binele comun stabilit exclusiv de individ: jos-dreapta, la extremă."}]},{"id":"3.14","type":"table","k":"13 · Sinteză","t":"Cine stabilește *binele comun*?","n":["Rezumă cele cinci răspunsuri.","Liberalismul: valoarea centrală este libertatea, iar binele comun îl stabilește fiecare individ, pentru sine.","Conservatorismul: ordinea și tradiția; binele comun îl stabilește comunitatea istorică.","Socialismul: egalitatea; binele comun îl stabilește colectivitatea.","Liberalismul social: libertatea și șansele egale; binele comun îl stabilesc indivizii, sprijiniți de stat.","Libertarianismul: libertatea față de stat; binele comun îl stabilește exclusiv individul."],"head":["Ideologia","Valoarea centrală","Cine stabilește binele comun"],"rows":[{"c":1,"cells":["Liberalismul","libertatea","fiecare individ, pentru sine"]},{"c":2,"cells":["Conservatorismul","ordinea, tradiția","comunitatea istorică"]},{"c":3,"cells":["Socialismul","egalitatea","colectivitatea"]},{"c":4,"cells":["Liberalismul social","libertatea și șansele egale","indivizii, sprijiniți de stat"]},{"c":5,"cells":["Libertarianismul","libertatea față de stat","exclusiv individul"]}]},{"id":"3.15","type":"procon","k":"14 · Critica ideologiilor: Marx","t":"Ideologia ca *mască*","img":"m3_masca","n":["Partea a doua a modulului nu mai cântărește o ideologie sau alta, ci gândirea ideologică însăși. Trei critici: Marx, Arendt, Popper.","Marx și Engels, în Ideologia germană: ideile dominante ale unei epoci sunt ideile clasei dominante.","Ideologia prezintă un interes particular ca interes general. De exemplu: piața liberă este bună pentru toți, spus de cei care câștigă din ea.","Pentru: critica permite identificarea intereselor nedeclarate din spatele unor idei prezentate ca neutre sau universale.","Contra: paradoxul autoreferinței, discutat de Karl Mannheim în 1929. Dacă orice idee ascunde un interes, același lucru e valabil și pentru marxism.","Iar în secolul douăzeci, marxismul a devenit ideologia oficială a unor regimuri totalitare."],"thesis":[{"c":1,"t":"ideile dominante = ideile clasei dominante"},{"c":2,"t":"un interes particular, prezentat ca interes general"}],"pro":[{"c":3,"h":"Interesele nedeclarate","p":"Le găsești în spatele ideilor „neutre” sau „universale”."}],"con":[{"c":4,"h":"Paradoxul autoreferinței","p":"Dacă orice idee ascunde un interes, și marxismul.","r":"Mannheim, 1929"},{"c":5,"h":"Ideologie oficială","p":"A unor regimuri totalitare în secolul XX."}]},{"id":"3.16","type":"media","k":"15 · Arendt, „Ideologie și teroare” (1953)","t":"Logica dusă până la *capăt*","video":"v_domino","img":"m3_domino","n":["Hannah Arendt, în eseul Ideologie și teroare, din 1953, inclus apoi în Originile totalitarismului, descrie ideologia totalitară prin trei trăsături.","Unu: pretinde că o singură idee, lupta claselor sau lupta raselor, explică întreaga istorie.","Doi: ignoră experiența. Faptele care o contrazic sunt declarate aparențe sau opera dușmanilor.","Trei: deduce din premisa inițială, fără oprire, până la consecințe extreme. Această gândire a pregătit teroarea regimurilor totalitare.","Pentru: analiza explică de ce oameni obișnuiți au putut accepta consecințe monstruoase. Nu printr-o adeziune la rău, ci prin consecvența logică dusă până la capăt.","Contra: analiza privește ideologiile totalitare, nu orice doctrină politică. Extinderea ei la liberalism sau la conservatorism nu este justificată automat."],"notes":[{"c":1,"n":"01","h":"O singură idee explică tot","p":"lupta claselor, lupta raselor"},{"c":2,"n":"02","h":"Ignoră experiența","p":"faptele incomode devin aparențe sau dușmani"},{"c":3,"n":"03","h":"Deduce fără oprire","p":"până la consecințe extreme"},{"c":4,"n":"+","h":"Pentru","p":"oameni obișnuiți, prin consecvență logică, nu prin adeziune la rău"},{"c":5,"n":"−","h":"Contra","p":"privește ideologiile totalitare, nu orice doctrină"}]},{"id":"3.17","type":"procon","k":"16 · Popper","t":"O teorie care explică *orice*","img":"m3_lebada","n":["Karl Popper, în Societatea deschisă și dușmanii ei, 1945, și în Conjecturi și infirmări, 1963.","O teorie care nu poate fi infirmată de niciun fapt nu este științifică. Ideologiile totale se confirmă mereu: orice eveniment le dă dreptate.","Planul de a reface întreaga societate cere constrângere. Alternativa este ingineria graduală: reforme parțiale, testabile, corectabile, într-o societate deschisă, în care orice idee poate fi criticată.","Pentru: criteriul oferă un test aplicabil oricărei ideologii, nu doar uneia anume.","Contra: criteriul falsificabilității este disputat în filosofia științei, de Thomas Kuhn și Imre Lakatos.","Iar componentele normative ale unei doctrine politice nu sunt teorii empirice. Criteriul li se aplică doar parțial, componentelor descriptive și predictive."],"thesis":[{"c":1,"t":"o teorie de neinfirmat nu e științifică; ideologiile totale se confirmă mereu"},{"c":2,"t":"ingineria graduală: reforme parțiale, testabile, corectabile"}],"pro":[{"c":3,"h":"Un test pentru oricine","p":"Se aplică oricărei ideologii, nu uneia anume."}],"con":[{"c":4,"h":"Falsificabilitatea, disputată","p":"În filosofia științei.","r":"Kuhn, Lakatos"},{"c":5,"h":"Normele nu sunt ipoteze empirice","p":"Criteriul se aplică doar părților descriptive și predictive."}]},{"id":"3.18","type":"cards","k":"17 · Sinteză didactică după Arendt și Popper","t":"Patru semne ale gândirii *ideologice*","cols":4,"n":["Din Arendt și Popper se poate extrage o sinteză didactică: patru semne ale gândirii ideologice.","Unu: explică totul. Nicio întrebare nu rămâne deschisă.","Doi: nu poate fi infirmată. Orice fapt devine o confirmare.","Trei: împarte lumea în noi și ei. Adversarul nu greșește, ci este rău.","Patru: scopul justifică mijloacele. Binele viitor scuză răul prezent."],"cards":[{"c":1,"n":"01","h":"Explică totul","p":"Nicio întrebare nu rămâne deschisă."},{"c":2,"n":"02","h":"Nu poate fi infirmată","p":"Orice fapt devine confirmare."},{"c":3,"n":"03","h":"„Noi” și „ei”","p":"Adversarul nu greșește, ci e rău."},{"c":4,"n":"04","h":"Scopul justifică mijloacele","p":"Binele viitor scuză răul prezent."}]},{"id":"3.19","type":"ex","ex":"signs","k":"Exercițiu · Detectează","t":"Detectorul de *ideologie*","n":["Cinci declarații ale unor mișcări imaginare. Pentru fiecare, bifează semnele gândirii ideologice pe care le recunoști. Poate fi unul, pot fi mai multe, poate fi niciunul.","Apasă Verifică pentru fiecare declarație."],"signs":["Explică totul","Nu poate fi infirmată","„Noi” și „ei”","Scopul justifică mijloacele"],"items":[{"t":"„Mișcarea noastră are răspuns la orice: istorie, economie, artă, familie. Nimic nu rămâne în afara ei.”","a":[0],"f":"Semnul 1: nicio întrebare nu rămâne deschisă."},{"t":"„Dacă datele ne contrazic, sunt falsificate. Dacă ne confirmă, iată dovada.”","a":[1],"f":"Semnul 2: orice fapt devine confirmare. Teoria nu mai poate fi testată (Popper)."},{"t":"„Cine nu e cu noi nu greșește pur și simplu: e un dușman al poporului.”","a":[2],"f":"Semnul 3: adversarul nu greșește, ci e rău."},{"t":"„Câteva nedreptăți azi sunt un preț mic pentru societatea perfectă de mâine.”","a":[3],"f":"Semnul 4: binele viitor scuză răul prezent. Amintește de ingineria utopică."},{"t":"„Propunem o reformă pe doi ani. Dacă indicatorii nu se îmbunătățesc, o oprim și o regândim.”","a":[],"f":"Niciun semn: o reformă parțială, testabilă și corectabilă, adică ingineria graduală a lui Popper."}]},{"id":"3.20","type":"stats","k":"18 · Ce spun cercetările","t":"Ideologia schimbă și *lectura faptelor*","n":["Trei cercetări empirice arată cum funcționează ideologia în gândirea oamenilor obișnuiți.","Philip Converse constată, pe date din Statele Unite ale anilor cincizeci, că doar aproximativ doi virgulă cinci la sută dintre cei intervievați foloseau coerent concepte ideologice, și circa cincisprezece la sută dintre votanți, dacă îi socotim și pe cei apropiați de acest nivel. Ideologiile sunt construite de elite, iar cercetări recente arată o creștere a coerenței ideologice.","Graham, Haidt și Nosek arată, în 2009, că cei care se declară liberali, în sens american, se sprijină mai ales pe grijă și corectitudine, iar conservatorii folosesc mai echilibrat cinci fundamente morale. Eșantioanele sunt majoritar americane, iar lista fundamentelor este disputată.","Kahan și colaboratorii săi arată, în 2017, că participanții buni la calcul interpretează corect date neutre, dar greșesc atunci când aceleași date le contrazic convingerile politice.","Concluzia: adversarii ideologici nu sunt neapărat imorali, ci pornesc de la intuiții morale diferite. Iar ideologia nu afectează doar opiniile, ci și lectura faptelor."],"stats":[{"c":1,"v":"≈ 2,5%","p":"foloseau coerent concepte ideologice (≈ 15% dintre votanți, cu cei apropiați)","r":"Converse, 1964 · date SUA, anii 1950","lim":"cercetări recente: coerența a crescut"},{"c":2,"v":"5","p":"fundamente morale; liberalii (sens american) se sprijină mai ales pe grijă și corectitudine","r":"Graham, Haidt și Nosek, 2009","lim":"eșantioane majoritar americane; lista e disputată"},{"c":3,"v":"date neutre ✓","p":"buni la calcul, dar greșesc când datele le contrazic convingerile","r":"Kahan et al., 2017","lim":""}],"foot":{"c":4,"t":"Ideologia nu afectează doar opiniile, ci și *lectura faptelor*."}},{"id":"3.21","type":"conclusion","k":"Concluzie","t":"Un răspuns, nu *singurul* răspuns","n":["Să recapitulăm. O ideologie este un sistem de idei care descrie, evaluează și prescrie.","Fiecare ideologie majoră răspunde unei probleme istorice reale: absolutismul, pentru liberalism; revoluția ca reconstrucție totală, pentru conservatorism; exploatarea industrială, pentru socialism; libertatea fără mijloace, pentru liberalismul social; planificarea centrală, pentru libertarianism.","Ideologiile se deosebesc prin răspunsul la întrebarea cine stabilește binele comun. Și o ideologie devine periculoasă când explică totul, nu poate fi infirmată și justifică orice mijloc.","Teza finală a modulului: o ideologie este un răspuns la o problemă reală și devine periculoasă atunci când pretinde că este singurul răspuns.","Și întrebarea care închide ciclul ne întoarce la începutul primului modul: dacă fiecare ideologie pornește de la o concepție despre om, mai putem spune, ca Aristotel, că omul este politic prin natură?"],"open":[{"c":1,"h":"Liberalismul","p":"absolutismul"},{"c":1,"h":"Conservatorismul","p":"revoluția ca reconstrucție totală"},{"c":1,"h":"Socialismul","p":"exploatarea industrială"},{"c":1,"h":"Liberalismul social","p":"libertatea fără mijloace"},{"c":1,"h":"Libertarianismul","p":"planificarea centrală"}],"work":{"c":2,"t":"Periculoasă când explică totul, nu poate fi infirmată și justifică orice mijloc."},"big":{"c":3,"t":"O ideologie este un răspuns la o problemă reală și devine periculoasă când pretinde că este *singurul* răspuns."},"next":{"c":4,"t":"Dacă fiecare ideologie pornește de la o concepție despre om, mai putem spune, ca Aristotel, că omul este politic prin natură?","m":"Înapoi la Modulul 01"}},{"id":"3.22","type":"quiz","k":"Verificare","t":"Cinci întrebări, cu *explicații*","n":["Verifică-te. Cinci întrebări, cu explicații după fiecare răspuns."],"qs":[{"q":"Care funcție deosebește ideologia de o teorie descriptivă?","o":["Descrie ce este greșit.","Evaluează cum ar trebui să fie.","Prescrie ce trebuie făcut.","Folosește concepte abstracte."],"a":2,"f":"Funcția practică: ideologia mobilizează spre acțiune."},{"q":"La ce problemă istorică a răspuns conservatorismul lui Burke?","o":["Revoluția industrială","Revoluția Franceză ca reconstrucție după un plan rațional","Economiile planificate ale secolului XX","Absolutismul monarhic"],"a":1,"f":"Burke (1790) apără instituțiile moștenite contra demolării și reconstrucției după un plan rațional."},{"q":"„Inegalitățile sunt acceptabile doar dacă îi avantajează pe cei mai defavorizați.” Ce principiu e acesta?","o":["Teoria îndreptățirii (Nozick)","Principiul diferenței (Rawls)","Argumentul epistemic (Burke)","Paradoxul autoreferinței (Mannheim)"],"a":1,"f":"Principiul diferenței, din O teorie a dreptății (1971), central pentru liberalismul social."},{"q":"„Orice s-ar întâmpla, teoria noastră are dreptate.” Ce critică i se potrivește cel mai bine?","o":["Popper: o teorie care nu poate fi infirmată nu e științifică.","Burke: tradiția conține experiența generațiilor.","Locke: munca fixează proprietatea.","Smith: piața produce prosperitate."],"a":0,"f":"Ideologiile totale se confirmă mereu; Popper le opune ingineria graduală."},{"q":"Ce arată Kahan et al. (2017)?","o":["Ideologia schimbă doar opiniile, nu și lectura datelor.","Cei buni la calcul greșesc când datele le contrazic convingerile politice.","Doar 2,5% dintre oameni știu să calculeze.","Toți folosesc aceleași fundamente morale."],"a":1,"f":"Aceleași date sunt citite corect când sunt neutre și greșit când contrazic convingerile."}]},{"id":"3.23","type":"ws","ws":"m3","k":"Fișă de lucru · Aplică","t":"Fișa ta de *lucru*","n":["Ultima fișă de lucru: ideologiile politice.","Trei etape: ce este o ideologie, ideologiile ca răspunsuri și critica lor. La final, feedback-ul.","Folosește indiciile dacă vrei să revezi un ecran. Întrebările deschise nu au un singur răspuns corect.","Fișa se salvează singură. Descarc-o și trimite-o profesorului tău."]},{"id":"3.24","type":"biblio","k":"Resurse","t":"Bibliografia *modulului*","n":["Bibliografia modulului trei: surse primare, lucrări didactice, exegeză și studii."],"bib":"m3"}]}],"bib":{"m1":[{"h":"Surse primare","items":["Aristotel, *Politica*, ed. a III-a, traducere și comentarii de Alexander Baumgarten, Univers Enciclopedic Gold, București, 2014 (seria Corpus Aristotelicum).","Aristotle, *Politics*, trad. Carnes Lord, ed. a 2-a, University of Chicago Press, Chicago, 2013.","Th. Hobbes, *Leviathan*, ed. Noel Malcolm, ed. a 2-a, Oxford University Press (Oxford World's Classics), Oxford, 2024. Ediția critică: *Leviathan*, ed. N. Malcolm, 3 vol., Clarendon Press, Oxford, 2012.","J.-J. Rousseau, *Discurs asupra originii și fundamentelor inegalității dintre oameni*, trad. S. Antoniu, Editura Științifică, București, 1958.","J.-J. Rousseau, *The Discourses and Other Early Political Writings*, ed. și trad. Victor Gourevitch, ed. a 2-a, Cambridge University Press, Cambridge, 2018.","J. Rawls, *O teorie a dreptății*, trad. Horia Târnovanu, Editura Universității „Alexandru Ioan Cuza”, Iași, 2011 (după ediția revizuită din 1999).","A. MacIntyre, *After Virtue*, ed. a 3-a, University of Notre Dame Press, Notre Dame, 2007.","M. J. Sandel, *Liberalism and the Limits of Justice*, ed. a 2-a, Cambridge University Press, Cambridge, 1998.","Ph. Pettit, *Republicanism: A Theory of Freedom and Government*, Oxford University Press, Oxford, 1997.","Q. Skinner, *Liberty before Liberalism*, Cambridge University Press, Cambridge, 1998."]},{"h":"Lucrări didactice","items":["W. Kymlicka, *Contemporary Political Philosophy: An Introduction*, ed. a 2-a, Oxford University Press, Oxford, 2002.","S. Mulhall, A. Swift, *Liberals and Communitarians*, ed. a 2-a, Blackwell, Oxford, 1996.","M. H. Hansen, *Polis: An Introduction to the Ancient Greek City-State*, Oxford University Press, Oxford, 2006."]},{"h":"Exegeză și studii","items":["J.-P. Vernant, *Les origines de la pensée grecque*, PUF, Paris, 1962.","R. Kraut, *Aristotle: Political Philosophy*, Oxford University Press, Oxford, 2002.","F. D. Miller Jr., *Nature, Justice, and Rights in Aristotle's Politics*, Clarendon Press, Oxford, 1995.","R. Tuck, *Hobbes: A Very Short Introduction*, Oxford University Press, Oxford, 2002.","F. Neuhouser, *Rousseau's Critique of Inequality: Reconstructing the Second Discourse*, Cambridge University Press, Cambridge, 2014.","Ch. Taylor, „Atomism”, în *Philosophical Papers*, vol. 2, Cambridge University Press, Cambridge, 1985.","Ch. Taylor, „Cross-Purposes: The Liberal-Communitarian Debate”, în N. Rosenblum (ed.), *Liberalism and the Moral Life*, Harvard University Press, Cambridge (Mass.), 1989.","A. Gutmann, „Communitarian Critics of Liberalism”, *Philosophy & Public Affairs* 14 (1985): 308–322.","S. M. Okin, *Justice, Gender, and the Family*, Basic Books, New York, 1989.","A. Patten, „The Republican Critique of Liberalism”, *British Journal of Political Science* 26 (1996): 25–44.","F. Warneken, M. Tomasello, „Altruistic helping in human infants and young chimpanzees”, *Science* 311 (2006): 1301–1303.","E. Fehr, S. Gächter, „Altruistic punishment in humans”, *Nature* 415 (2002): 137–140.","J. Holt-Lunstad, T. B. Smith, J. B. Layton, „Social relationships and mortality risk: a meta-analytic review”, *PLoS Medicine* 7 (2010): e1000316.","E. Ostrom, *Governing the Commons*, Cambridge University Press, Cambridge, 1990."]}],"m2":[{"h":"Surse primare","items":["Herodotus, *The Landmark Herodotus: The Histories*, ed. R. B. Strassler, trad. A. L. Purvis, Pantheon, New York, 2007 (cartea a III-a, 80–82).","Platon, *Opera integrală*, vol. III: *Cleitophon. Republica (Statul)*, traducere, introduceri și note de Andrei Cornea, Humanitas, București, 2022 (cărțile VI, VIII–IX).","Aristotel, *Politica*, ed. a III-a, traducere și comentarii de Alexander Baumgarten, Univers Enciclopedic Gold, București, 2014 (cărțile III–V).","Aristotle, *Politics*, trad. Carnes Lord, ed. a 2-a, University of Chicago Press, Chicago, 2013.","Th. Hobbes, *Leviathan*, ed. Noel Malcolm, ed. a 2-a, Oxford University Press (Oxford World's Classics), Oxford, 2024 (cap. XIII, XIX).","Flavius Josephus, *Against Apion*, traducere și comentariu de J. M. G. Barclay, Brill, Leiden, 2007 (II.165).","J. Locke, *A Letter Concerning Toleration and Other Writings*, ed. Mark Goldie, Liberty Fund, Indianapolis, 2010.","Montesquieu, *The Spirit of the Laws*, ed. și trad. A. M. Cohler, B. C. Miller, H. S. Stone, Cambridge University Press, Cambridge, 1989 (cartea XI).","A. de Tocqueville, *Democracy in America*, ed. și trad. H. C. Mansfield, D. Winthrop, University of Chicago Press, Chicago, 2000 (vol. I, partea a II-a, cap. 7).","P.-J. Proudhon, *What Is Property?*, ed. și trad. D. R. Kelley, B. G. Smith, Cambridge University Press, Cambridge, 1994.","R. P. Wolff, *In Defense of Anarchism*, University of California Press, Berkeley, 1998 (ed. originală: 1970).","K. R. Popper, *Societatea deschisă și dușmanii ei*, vol. I: *Vraja lui Platon*, Humanitas, București, 2005 (cap. 7 și 9).","H. Arendt, *Originile totalitarismului*, trad. Ion Dur și Mircea Ivănescu, ed. a III-a, Humanitas, București, 2014."]},{"h":"Lucrări didactice","items":["R. A. Dahl, *Democracy and Its Critics*, Yale University Press, New Haven, 1989.","G. Sartori, *The Theory of Democracy Revisited*, 2 vol., Chatham House, Chatham (N.J.), 1987.","B. Manin, *The Principles of Representative Government*, Cambridge University Press, Cambridge, 1997.","M. H. Hansen, *The Athenian Democracy in the Age of Demosthenes*, ed. a 2-a, Bristol Classical Press, London, 1999."]},{"h":"Exegeză și studii","items":["J. Annas, *An Introduction to Plato's Republic*, Clarendon Press, Oxford, 1981.","R. Kraut, *Aristotle: Political Philosophy*, Oxford University Press, Oxford, 2002.","J. N. Shklar, *Montesquieu*, Oxford University Press, Oxford, 1987.","M. Canovan, *Hannah Arendt: A Reinterpretation of Her Political Thought*, Cambridge University Press, Cambridge, 1992.","J. J. Linz, *Totalitarian and Authoritarian Regimes*, Lynne Rienner, Boulder, 2000.","A. Sen, *Poverty and Famines*, Clarendon Press, Oxford, 1981; *Development as Freedom*, Oxford University Press, Oxford, 1999.","D. Acemoglu, S. Naidu, P. Restrepo, J. A. Robinson, „Democracy Does Cause Growth”, *Journal of Political Economy* 127 (2019): 47–100.","S. Milgram, „Behavioral Study of Obedience”, *Journal of Abnormal and Social Psychology* 67 (1963): 371–378.","J. M. Burger, „Replicating Milgram: Would People Still Obey Today?”, *American Psychologist* 64 (2009): 1–11.","G. Perry, *Behind the Shock Machine*, Scribe, Melbourne, 2012."]}],"m3":[{"h":"Surse primare","items":["J. Locke, *Two Treatises of Government*, ed. Peter Laslett, Cambridge University Press, Cambridge, 1988 (Al doilea tratat, § 28).","A. Smith, *An Inquiry into the Nature and Causes of the Wealth of Nations*, ed. R. H. Campbell, A. S. Skinner, 2 vol., Clarendon Press, Oxford, 1976 (Glasgow Edition).","E. Burke, *Reflecții asupra Revoluției din Franța*, traducere, studiu introductiv și note de Mihaela Czobor-Lupp, Nemira, București, 2000. Ediția critică: *Reflections on the Revolution in France*, ed. J. C. D. Clark, Stanford University Press, Stanford, 2001.","J.-J. Rousseau, *Discurs asupra originii și fundamentelor inegalității dintre oameni*, trad. S. Antoniu, Editura Științifică, București, 1958.","K. Marx, F. Engels, *The German Ideology*, în *Collected Works*, vol. 5, Lawrence & Wishart, London, 1976.","K. Marx, *Later Political Writings*, ed. și trad. Terrell Carver, Cambridge University Press, Cambridge, 1996 (include *Manifestul Partidului Comunist*).","T. H. Green, *Lectures on the Principles of Political Obligation and Other Writings*, ed. P. Harris, J. Morrow, Cambridge University Press, Cambridge, 1986 (include „Liberal Legislation and Freedom of Contract”).","J. Rawls, *O teorie a dreptății*, trad. Horia Târnovanu, Editura Universității „Alexandru Ioan Cuza”, Iași, 2011.","F. A. Hayek, *The Road to Serfdom: Text and Documents. The Definitive Edition*, ed. Bruce Caldwell, University of Chicago Press, Chicago, 2007.","R. Nozick, *Anarchy, State, and Utopia*, Basic Books, New York, 2013 (cu un cuvânt înainte de Thomas Nagel; ed. originală: 1974).","H. Arendt, „Ideology and Terror: A Novel Form of Government”, *The Review of Politics* 15 (1953): 303–327; *Originile totalitarismului*, trad. Ion Dur și Mircea Ivănescu, ed. a III-a, Humanitas, București, 2014.","K. R. Popper, *Societatea deschisă și dușmanii ei*, vol. I, Humanitas, București, 2005; *Conjectures and Refutations*, Routledge Classics, London, 2002 (ed. originală: 1963).","K. Mannheim, *Ideology and Utopia*, Harcourt, Brace & Co., New York, 1936 (ed. originală: 1929)."]},{"h":"Lucrări didactice","items":["A. Heywood, *Political Ideologies: An Introduction*, ed. a 7-a, Red Globe Press (Bloomsbury), London, 2021.","M. Freeden, *Ideology: A Very Short Introduction*, Oxford University Press, Oxford, 2003.","M. Freeden, L. T. Sargent, M. Stears (ed.), *The Oxford Handbook of Political Ideologies*, Oxford University Press, Oxford, 2013.","T. Eagleton, *Ideology: An Introduction*, ed. nouă, Verso, London, 2007.","W. Kymlicka, *Contemporary Political Philosophy: An Introduction*, ed. a 2-a, Oxford University Press, Oxford, 2002.","A.-P. Iliescu, *Conservatorismul anglo-saxon*, Editura All, București, 1994.","A.-P. Iliescu, *Liberalismul – între succese și iluzii*, Editura All, București, 1998."]},{"h":"Exegeză și studii","items":["M. Canovan, *Hannah Arendt: A Reinterpretation of Her Political Thought*, Cambridge University Press, Cambridge, 1992.","Ph. Converse, „The Nature of Belief Systems in Mass Publics”, în D. Apter (ed.), *Ideology and Discontent*, Free Press, New York, 1964.","J. Graham, J. Haidt, B. Nosek, „Liberals and Conservatives Rely on Different Sets of Moral Foundations”, *Journal of Personality and Social Psychology* 96 (2009): 1029–1046.","D. M. Kahan, E. Peters, E. C. Dawson, P. Slovic, „Motivated Numeracy and Enlightened Self-Government”, *Behavioural Public Policy* 1 (2017): 54–86."]}]},"ws":{"m1":{"series":"Viața în cetate · Cursul 1","title":"Natura umană și comunitatea","mod":"01","how":"După fiecare etapă a modulului, răspunde scurt, în unul sau două rânduri. La final, completează feedback-ul.","stages":[{"h":"Etapa 1 · Cetatea grecească și clasicii","to":"1.15","qs":[{"id":"q1","n":1,"k":"conținut","see":"1.10","t":"Ce are omul și nu au celelalte animale, după Aristotel? La ce îi folosește?"},{"id":"q2","n":2,"k":"conținut","see":"1.11","t":"Ce se întâmplă, după Hobbes, când oamenii trăiesc fără o putere comună?"},{"id":"q3","n":3,"k":"deschisă","see":"1.8","t":"Cu care dintre cei trei autori ești cel mai mult de acord? Spune de ce, într-o frază."}]},{"h":"Etapa 2 · Autonomie și datorie civică","to":"1.21","qs":[{"id":"q4","n":4,"k":"conținut","see":"1.17","t":"Ce înseamnă, în viziunea liberală, că statul este neutru?"},{"id":"q5","n":5,"k":"conținut","see":"1.18","t":"Dă un exemplu de obligație care, în viziunea comunitaristă, nu provine din consimțământ."},{"id":"q6","n":6,"k":"deschisă","see":"1.20","t":"Ar trebui școala să formeze elevii într-o anumită concepție despre viața bună? Răspunde într-o frază, din perspectiva uneia dintre cele trei viziuni."}]},{"h":"Etapa 3 · Ce arată studiile","to":null,"qs":[{"id":"q7","n":7,"k":"conținut","see":"1.22","t":"Ce s-a întâmplat cu cooperarea în jocul lui Fehr și Gächter atunci când trișorii nu puteau fi pedepsiți?"},{"id":"q8","n":8,"k":"conținut","see":"1.22","t":"Numește două condiții care permit unei comunități să-și gestioneze singură resursele comune, după Ostrom.","note":"Ecranul despre cercetări numește studiul; condițiile sunt descrise în Ostrom, Governing the Commons (1990), din bibliografie."},{"id":"q9","n":9,"k":"deschisă","see":"1.22","t":"Care dintre limitele discutate se vede cel mai bine într-o comunitate din care faci parte (clasa, echipa, cartierul)?"}]}],"fb":{"h":"Feedback · Cum ți s-a părut modulul?","likert":["Am înțeles ideile principale.","Exemplele și studiile m-au ajutat să înțeleg.","Ritmul a fost potrivit.","Mi-ar plăcea să parcurg și următorul modul."],"qs":[{"id":"q10","n":10,"t":"Ce idee ți-a rămas în minte?"},{"id":"q11","n":11,"t":"Ce ar trebui schimbat sau explicat mai bine data viitoare?"}]}},"m2":{"series":"Viața în cetate · Cursul 2","title":"Regimurile politice","mod":"02","how":"După fiecare etapă a modulului, răspunde scurt, în unul sau două rânduri. La final, completează feedback-ul.","stages":[{"h":"Etapa 1 · Scurtă istorie a ideii de regim","to":"2.11","qs":[{"id":"q1","n":1,"k":"conținut","see":"2.1","t":"Ce este un regim politic?"},{"id":"q2","n":2,"k":"conținut","see":"2.10","t":"După ce două criterii împarte Aristotel regimurile politice?"},{"id":"q3","n":3,"k":"conținut","see":"2.11","t":"Care este diferența dintre o formă dreaptă și o formă deviată a unui regim?"}]},{"h":"Etapa 2 · Regimuri reale","to":"2.16","qs":[{"id":"q4","n":4,"k":"conținut","see":"2.14","t":"Dă un argument pentru democrație."},{"id":"q5","n":5,"k":"conținut","see":"2.12","t":"Ce dificultate are monarhia?"}]},{"h":"Etapa 3 · Limitele regimului","to":null,"qs":[{"id":"q6","n":6,"k":"conținut","see":"2.18","t":"Ce este o distopie? Numește un roman distopic."},{"id":"q7","n":7,"k":"deschisă","see":"2.22","t":"De ce crezi că puterea trebuie limitată?"}]}],"fb":{"h":"Feedback · Cum ți s-a părut modulul?","likert":["Am înțeles ideile principale.","Exemplele și studiile m-au ajutat să înțeleg.","Ritmul a fost potrivit.","Mi-ar plăcea să parcurg și următorul modul."],"qs":[{"id":"q8","n":8,"t":"Ce idee ți-a rămas în minte?"},{"id":"q9","n":9,"t":"Ce ar trebui schimbat sau explicat mai bine data viitoare?"}]}},"m3":{"series":"Viața în cetate · Cursul 3","title":"Ideologiile politice","mod":"03","how":"După fiecare etapă a modulului, răspunde scurt, în unul sau două rânduri. La final, completează feedback-ul.","stages":[{"h":"Etapa 1 · Ce este o ideologie","to":"3.3","qs":[{"id":"q1","n":1,"k":"conținut","see":"3.1","t":"Ce este o ideologie?"},{"id":"q2","n":2,"k":"conținut","see":"3.1","t":"Care sunt cele trei funcții ale unei ideologii?"},{"id":"q3","n":3,"k":"conținut","see":"3.2","t":"Prin ce se deosebește filosofia politică de o ideologie?"}]},{"h":"Etapa 2 · Ideologiile ca răspunsuri","to":"3.14","qs":[{"id":"q4","n":4,"k":"conținut","see":"3.4","t":"Alege o ideologie și spune la ce problemă a răspuns."}]},{"h":"Etapa 3 · Critica ideologiilor","to":null,"qs":[{"id":"q5","n":5,"k":"conținut","see":"3.18","t":"Numește un semn al gândirii ideologice."},{"id":"q6","n":6,"k":"deschisă","see":"3.16","t":"Când crezi că o ideologie devine periculoasă?"}]}],"fb":{"h":"Feedback · Cum ți s-a părut modulul?","likert":["Am înțeles ideile principale.","Exemplele și studiile m-au ajutat să înțeleg.","Ritmul a fost potrivit.","Mi-ar plăcea să parcurg și următorul modul."],"qs":[{"id":"q7","n":7,"t":"Ce idee ți-a rămas în minte?"},{"id":"q8","n":8,"t":"Ce ar trebui schimbat sau explicat mai bine data viitoare?"}]}}}};
window.ALT={"c_start":"Piață veche central-europeană, alb-negru: fațade baroce și o coloană monument în centru, în zori.","m1_cover":"Loc de adunare grecesc antic pe o colină: trepte de piatră tăiate în stâncă și o tribună, deasupra mării.","m1_physis":"Un măslin bătrân crește printr-un zid de piatră uscată: jumătate natură, jumătate construcție.","m1_polis2":"Reconstituire aeriană a unei cetăți grecești antice la mare: acropolă cu templu, agoră cu stoa, teatru, port. Ilustrație.","m1_lege2":"Stelă de marmură cu o lege grecească arhaică, litere grecești săpate pe rânduri. Ilustrație.","m1_sofisti":"Atena, secolul V î.Hr.: un sofist discută cu tineri sub coloanele unei stoa; unul arată spre o tablă de lege. Ilustrație.","m1_agora":"Agora Atenei: doi cetățeni în himation discută; în jur, oameni, tarabe și o stoa; Acropola în fundal. Ilustrație.","m1_pact":"Natură statică din secolul XVII: o sabie peste un pact de pergament cu sigiliu roșu de ceară, la lumina lumânării.","m1_dans":"Sat francez din secolul XVIII, la apus: oamenii dansează în jurul unui stejar și se privesc unii pe alții. Ilustrație.","m2_liceu":"Liceul lui Aristotel: un învățat compară două suluri de papirus; în spate, rafturi cu sute de suluri. Ilustrație.","m2_persia_multi":"Relief persan de la Persepolis: o procesiune lungă cu multe delegații, pe mai multe registre. Ilustrație.","m2_persia_rege":"Relief persan: un rege singur pe tron, cu un sceptru lung. Ilustrație.","m2_total":"Fotografie de arhivă, anii 1930: un stadion uriaș, mii de oameni în uniforme identice, așezați în blocuri. Ilustrație.","m3_presa":"Tipografie din secolul XIX: o presă de fier și pamflete puse la uscat pe sfori.","m1_cosmos":"Urme de stele pe cer, deasupra siluetei coloanelor unui templu grecesc.","m1_atena":"Acropola din Atena văzută dintr-o colină apropiată, în zori, cu orașul în ceață.","m1_aristotel":"Bustul de marmură al lui Aristotel, într-un muzeu.","m1_hobbes":"Văzută de sus, o mulțime uriașă de oameni formează silueta unui uriaș încoronat cu brațele deschise.","m1_usa":"O ușă grea de lemn, noaptea, cu o cheie în broasca de fier și o dungă de lumină dedesubt.","m1_rousseau":"Un om singur, mic, merge printr-o pădure străveche cu copaci uriași, în ceața dimineții.","m1_val":"Siluete anonime de oameni în spatele unui văl alb translucid, în contralumină.","m1_comunitate":"Mâinile unei femei în vârstă țin o fotografie veche; pe masă, scrisori și poze de familie.","m1_adunare":"Adunare într-o sală de cartier: oameni de vârste diferite, văzuți din spate, ridică mâna.","m2_cover":"Coloane neoclasice masive ale unei clădiri publice; un om mic urcă treptele late.","m2_persia":"Relief antic în piatră, în stil persan: un șir de nobili bărboși, din profil. Ilustrație.","m2_corabia_gr":"Corabie grecească antică cu o singură velă, pe mare furtunoasă; marinarii se luptă pentru vâsla-cârmă.","m2_cantar":"Balanță veche de alamă, cu talerele în echilibru.","m2_coroana":"O coroană regală pe o pernă de catifea, într-o sală goală.","m2_urna":"O mână introduce un buletin de vot împăturit într-o urnă transparentă.","m2_templu":"Interiorul gol al unui templu de piatră, cu raze de lumină care cad pe podea.","m2_tron":"Un tron gol într-o sală părăsită, cu praf în lumină.","m2_oi":"O turmă de oi pe o pășune englezească împrejmuită cu ziduri de piatră.","m2_camere":"Un perete plin cu zeci de camere de supraveghere îndreptate în aceeași direcție.","m2_panou":"Panou de control de laborator din anii 1960: un șir de comutatoare și un cadran; o mână ezită.","m3_cover":"Mulțime la o manifestație pașnică, văzută din spate, cu pancarte albe, fără text.","m3_carte":"Un dicționar vechi deschis și o lupă.","m3_fabrica":"Fabrică textilă din secolul al XIX-lea: șiruri de războaie de țesut și muncitori.","m3_liberal":"Piață veche în zori: tarabe, negustori și cumpărători.","m3_radacini":"Rădăcinile uriașe ale unui stejar bătrân care se prind de pământ și de pietre.","m3_social":"Coridorul unei școli vechi, cu lumina ferestrelor pe podea.","m3_cheie":"O poartă de fier forjat încuiată cu un lacăt, în fața unei grădini private.","m3_gard":"Pe o pășune comună, un om bate pari de gard; sătenii privesc de departe.","m3_masca":"O mască albă de teatru pe catifea întunecată.","m3_domino":"Un șir lung și șerpuit de piese de domino; primele cad.","m3_lebada":"O lebădă neagră înoată printre multe lebede albe.","m3_vot":"Secție de votare de la începutul secolului XX: urnă de lemn și oameni la coadă.","v_leviathan":"Clip: mulțimea care formează uriașul se mișcă încet, văzută de sus.","v_val":"Clip: vălul alb se mișcă ușor în fața siluetelor.","v_corabia":"Clip: corabia grecească în furtună; marinarii trag vâsla-cârmă în direcții diferite.","v_camere":"Clip: camerele de supraveghere se rotesc toate deodată spre privitor.","v_gard":"Clip: omul bate un par de gard în pământul comun.","v_domino":"Clip: piesele de domino cad una după alta."};
